import json, re, copy
from pathlib import Path

root = Path(__file__).parent
original_path = root/'course-original.json'
if not original_path.exists():
    original_path.write_text((root/'course.json').read_text())
original = json.loads(original_path.read_text())
entries = {}

# Focused examples below are project fragments: imports/dependencies and services
# are described by the chapter workshop rather than silently implied runnable code.

def compact(module, rows):
    add(module, rows)
def add(module, rows):
    for row in rows:
        topic, explanation, code, output, trace, mistake, diagram = row
        entries[(module, topic)] = dict(explanation=explanation, code=code, output=output, trace=trace, mistake=mistake, diagram=diagram.split(' > '))

add(23, [
('Docker Basics', 'Docker image application filesystem/config template hai; container running isolated process instance hai. Container full hardware VM nahi. Ports expose/publish distinction aur volume persistence understand karo. QA dependency version repeatable environment mein start kar sakti hai. Container health business correctness equivalent nahi.', 'docker run --rm -p 5432:5432 -e POSTGRES_PASSWORD=local-dev postgres:16-alpine', 'Starts a disposable local PostgreSQL container if Docker and image access work.', 'Image postgres16-alpine select hoti hai. Port mapping host5432 to container5432 hai. --rm exit ke baad container remove karti hai; separate named volume ho to data rules differ hain. Example password local demo only.', 'Image pull/start database readiness prove nahi. Host port busy ho to mapping change karo.', 'Versioned image > Running container > Published service port'),
('Dockerfile', 'Dockerfile image build steps declare karta hai. FROM base runtime choose, COPY artifact add aur ENTRYPOINT process configure karta hai. App build separate stage ya prebuilt artifact workflow ho sakta hai. Image/runtime JDK compatible rakho. Small image automatically secure/correct nahi; dependency ownership still important hai.', 'FROM eclipse-temurin:21-jre\nWORKDIR /app\nCOPY target/lab.jar app.jar\nENTRYPOINT ["java", "-jar", "app.jar"]', 'docker build creates an image only after target/lab.jar exists.', 'Runtime base Java21 support karti hai. COPY exact build artifact path require karta hai. Exec-form entrypoint signal delivery cleaner banati hai. Maven finalName align karo.', 'Wildcard target/*.jar multiple artifacts accidentally copy kar sakta hai. Image mein secrets bake mat karo.', 'Built JAR > Dockerfile image layers > Java process'),
('Docker Compose', 'Compose multiple local services ka declarative environment manage karta hai. Service DNS name containers ke beech resolve hota hai; localhost same container ko refer karta hai. Depends-on startup order readiness necessarily guarantee nahi without health conditions/config. Persistent volumes cleanup policy explicitly choose karo.', 'services:\n  db:\n    image: postgres:16-alpine\n    environment:\n      POSTGRES_PASSWORD: local-dev\n    ports:\n      - "5432:5432"', 'docker compose up starts the declared DB; app service is not defined here.', 'Compose project service db create karta hai. App inside same network jdbc:postgresql://db:5432/... use kare; host-launched app localhost published port use kare.', 'Container app localhost DB refer nahi karta unless same container. down -v persisted data remove kar sakta hai; scope know karo.', 'Compose definitions > Local service network > Dependencies'),
('Testcontainers', 'Testcontainers test lifecycle ke saath Docker dependencies create karta hai, app packaging ka replacement nahi. Dynamic connection properties running container ke mapped addresses wire karte hain. Integration tests actual DB engine use karke Flyway/query behavior cover karti hain. Version-specific modules/imports dependency docs se align karo.', '@DynamicPropertySource\nstatic void databaseProperties(DynamicPropertyRegistry registry) {\n    registry.add("spring.datasource.url", db::getJdbcUrl);\n    registry.add("spring.datasource.username", db::getUsername);\n    registry.add("spring.datasource.password", db::getPassword);\n}', 'Wires a started PostgreSQLContainer into a Boot test context.', 'Registry supplier values container actual endpoints se resolve karti hai. db declaration, @Testcontainers lifecycle and drivers required. Dynamic port hardcoded assumptions remove karti hai.', 'Container starts after datasource initialization ho to setup fail. Fake/in-memory DB aur real container distinction clear rakho.', 'Disposable DB starts > Dynamic properties > Real repository tests'),
('Jenkins/GitHub Actions', 'CI pipeline fresh environment mein checkout, build aur tests repeatably run karti hai. Jenkins aur GitHub Actions different config syntax use karte hain but same lifecycle principles. Reports/artifacts retain karo to failed run diagnose ho. Versioned JDK/dependencies reproducibility improve karti hain. Secrets secure runtime inputs hon.', '# GitHub Actions job fragment:\nsteps:\n  - uses: actions/checkout@v4\n  - uses: actions/setup-java@v4\n    with:\n      distribution: temurin\n      java-version: "21"\n      cache: maven\n  - run: mvn -B verify', 'Requires an enclosing workflow/job with a configured runner.', 'Checkout source fetch karta hai. setup-java JDK provide karti hai. verify configured test lifecycle execute karta hai. Integration dependencies Docker availability runner par depend karti hain.', 'Pipeline green skipped tests ya missing assertions ke saath misleading ho sakti hai. Actions versions maintain/pin policy follow karo.', 'Checkout + JDK > Maven verify > Reports and gate outcome'),
('Quality Gates', 'Quality gate objective release criteria evaluate karti hai: meaningful tests pass, critical scans acceptable, contract compatibility verified. Coverage percent code execution measure hai, assertion quality nahi. Flaky tests quarantine tracking ke saath handle karo. Fast feedback aur realistic integration balance chahiye.', '// Gate policy example:\n// Unit + component checks pass\n// Provider contracts verified\n// No unresolved critical vulnerability per project policy\n// New payment behavior has meaningful regression assertions', 'Policy outline; configure executable checks in the actual CI pipeline.', 'Gate result specific evidence se linked honi chahiye. New behavior validation test quality review demand karti hai. Trend/ownership flaky tests continuously track kare.', '100% line coverage business correctness prove nahi. Disabled failing tests ko silently green success treat mat karo.', 'Required checks > Evidence evaluation > Release decision'),
])

add(24, [
('Spring AI Introduction', 'Spring AI model providers aur AI application building blocks ke liye Spring-friendly abstractions deta hai. Model client, embedding/vector retrieval aur tool/advisor concepts related but separate hain. SDK/model version compatibility verify karo. QA controlled model boundary se business flow test kar sakti hai, real nondeterministic model evaluations separately.', '// Architecture boundary illustration:\ninterface AnswerModel { String answer(String context, String question); }\n// Inject a fake for deterministic tests; adapt Spring AI in production.', 'Plain Java interface; no model/provider is contacted by this declaration.', 'Boundary model dependency replaceable banati hai. Adapter actual provider integration own kare. Credentials, prompt budget and timeout real setup required hain.', 'AI library add karna truthful answers guarantee nahi. API keys repository/browser code mein expose mat karo.', 'Application contract > Spring AI adapter > Model provider'),
('ChatClient', 'ChatClient prompt-building fluent API aur model call abstraction deta hai. user request, system guidance aur output extraction separate roles hain. Synchronous call vs streaming behavior API/version-specific hai. QA fake response se downstream validation test kare, real provider cost/latency/nondeterminism measured evaluation mein cover kare.', '// Spring AI project fragment:\nString answer = chatClient.prompt()\n    .system("Answer only from supplied evidence.")\n    .user(question)\n    .call().content();', 'Configured ChatClient invokes a model and returns its content.', 'Injected client provider/config carry karta hai. prompt roles build karta hai; call executes external generation. Question alone evidence supply nahi karti, RAG context separately include chahiye.', 'Prompt instruction enforceable permission boundary nahi. Null/empty/malformed model output validate karo.', 'Prompt roles > Configured model call > Validate content'),
('Prompt Templates', 'Prompt template reusable instructions ke saath runtime variables interpolate karti hai. Variable inputs data hain, trusted instructions automatically nahi. Requirements excerpts untrusted command-like text contain kar sakte hain; clear delimitation and operation constraints useful hain. Template tests rendered input verify karti hain before expensive model evaluation.', '// Template concept (not a specific SDK constructor):\nString prompt = "Evidence:\n" + evidence + "\nQuestion:\n" + question\n    + "\nState when the evidence is insufficient.";', 'Builds prompt text; model execution still separate.', 'Evidence aur question explicit labels se role clear hote hain. Template size token budget consider karta hai. Library templating syntax/version docs follow karo for escaping substitutions.', 'String interpolation prompt injection eliminate nahi karti. Source content ko tool authorization instruction treat mat karo.', 'Template + variables > Rendered prompt > Model evaluation'),
('Structured Output', 'Structured output model response ko desired schema/domain object mein parse karne ka approach hai. JSON syntax valid hona business values correct hona prove nahi. Required fields, enums, bounds aur evidence references validate karo. Provider-native schema support aur prompt-based conversion capabilities differ hain. Parse failure explicit error path deserve karti hai.', 'record TestCaseDraft(String title, java.util.List<String> steps, String expected) {}\n// Spring AI fragment:\nTestCaseDraft draft = chatClient.prompt().user(request).call().entity(TestCaseDraft.class);', 'Attempts typed conversion; requires configured compatible client and output.', 'Record target fields define karta hai. Conversion/deserialization successful ho tab bhi expected requirement match manually/evaluation check chahiye. Nullable/missing fields validation add karo.', 'Generated expected result incorrect ho to perfect JSON bhi useless test banati hai. Catch parse errors intentionally.', 'Generated output > Parse schema > Validate business fields'),
('Tool Calling', 'Tool calling model ko structured operation request propose karne deta hai. Application validates and executes authorized tool, result model context mein feed hota hai. Model tool name choose kare to permission automatically nahi milti. Read-only test lookup aur production deployment ka impact different hai. Scope and arguments execution boundary par enforce karo.', '// Tool-boundary illustration:\nString readTestResult(String runId) {\n    authorizeRead(runId);\n    return resultStore.load(runId);\n}\n// Framework registration / schema configured separately.', 'Authorized result lookup only after application permission validation.', 'Model proposed run ID validated hai. Tool store actual evidence return karta hai. Unknown/stale ID explicit failure de. Side effects need requested operation scope.', 'Model output ko direct shell command mat execute karo. Tool metadata alone actual enforcement nahi.', 'Model proposal > Validate / authorize > Execute tool + evidence'),
('Embeddings', 'Embedding text ko numeric vector represent karti hai for similarity operations. Same compatible model/dimension query aur documents ke liye use karo. Similarity semantic relatedness suggest karti hai, factual truth nahi. Model change corpus re-embedding/index migration require kar sakta hai. QA known queries ke relevant evidence retrieval verify kare.', '// Conceptual embedding contract:\ninterface Embedder { float[] embed(String text); }\nfloat[] queryVector = embedder.embed("payment retry rules");', 'Numeric vector from a configured embedding model, dimensions model-specific.', 'Text vector query index compare karega. Keyword exact ID and semantic query different retrieval needs hain. Permissions filter separately apply karo, vector similarity authorization nahi.', 'Two vectors different model spaces mein compare meaningful nahi. PII external embed API bhejne ka data policy follow karo.', 'Text query > Compatible embedding model > Similarity vector'),
('Vector Stores', 'Vector store document embeddings aur metadata index/store karti hai. Search top-k similar pieces retrieve karta hai. Metadata source IDs/version/access scope carry kar sakti hai. Similarity score threshold empirical evaluation se choose karo. Store existence RAG answer grounding automatically implement nahi karta.', '// Spring AI fragment, store setup required:\nvar documents = vectorStore.similaritySearch(\n    org.springframework.ai.vectorstore.SearchRequest.builder()\n        .query(question).topK(3).build());', 'Returns configured store search results, possibly empty.', 'Query configured embedding model ke through vectorize ho sakti hai. topK maximum matches control karta hai, relevance guarantee nahi. Access filters must be applied for the actual corpus.', 'Global index query bina tenant/access filter private evidence leak kar sakti hai. Nearest result insufficient ho sakta hai.', 'Embedded corpus > Filtered top-k search > Evidence documents'),
('Advisors', 'Advisors model call ke around reusable request/response behavior attach kar sakte hain, jaise retrieval augmentation ya conversational memory. Order interactions matter: context added before generation aur logging privacy policy align ho. Advisor wiring framework/version-specific hai. QA resulting prompt and response paths inspect kare, config name alone success nahi.', '// Pipeline concept:\n// User request -> retrieval advisor -> model -> response validation\n// Configure actual Advisor types for the chosen Spring AI release.', 'Pipeline illustration; no advisor instance is installed by these comments.', 'Retrieval enriches evidence. Response validation unsupported claims flag kar sakti hai. Memory lifetime user isolation follow kare. Actual SDK setup official version docs se choose karo.', 'Memory advisor authorization-aware retrieval replace nahi karta. Advisor order token use/behavior change kar sakti hai.', 'User request > Advisor augmentation > Model + response checks'),
('Observability', 'AI observability latency, token/cost usage, provider errors aur retrieval quality ko connect karti hai. Prompt/response logging sensitive source text expose kar sakti hai, so minimize and scope. QA generation ID ke through exact evidence/prompt version/result trace kar sakti hai. Metrics confidence/accuracy replace nahi karti.', '// Evaluation record concept:\nrecord GenerationTrace(String generationId, String promptVersion,\n                       java.util.List<String> sourceIds, long elapsedMillis) {}', 'Metadata links a generation to its version and retrieved evidence.', 'Generation identifier repeatable investigation enable karta hai. Source IDs audit retriever output trace karte hain. Cost/usage provider metrics separately capture karein.', 'Full secret-containing prompt log mat karo. Low latency inaccurate answer ko acceptable nahi banati.', 'Generation + source IDs > Telemetry > Reproducible evaluation'),
])

add(25, [
('RAG Basics', 'Retrieval-Augmented Generation mein answer se pehle relevant external evidence fetch hoti hai. Documents ingest/index, query retrieve, selected context prompt aur generation distinct stages hain. QA acceptance criteria aur existing tests retrieve karke gaps explain kar sakti hai. Retrieval miss ho to fluent answer still wrong ho sakta hai; unsupported case mein insufficient evidence state karo.', '// Conceptual interfaces, not a connected provider:\nvar evidence = retriever.search(question, userScope);\nString answer = model.answer(evidence, question);\n// Verify claimed source IDs exist in retrieved evidence.', 'Pseudo-code: requires retriever, access scope and model adapters.', 'Evidence retrieval permissions apply karti hai. Model context relevant limited sources include karta hai. Final claims source version se tied honi chahiye. Retrieval/model/citation quality separately evaluate karo.', 'RAG hallucination eliminate nahi karti. Retrieved document command text tool execution authorization nahi.', 'Question > Authorized retrieval > Evidence-grounded answer'),
('Chunking', 'Chunking documents ko retrievable coherent sections split karti hai. Heading, requirement ID aur source/version retain karo. Very small chunks context lose; large chunks irrelevant text/token load la sakte hain. Overlap boundaries connect kar sakta hai but duplicates bhi introduce karta hai. Best size actual corpus questions se measure karo.', 'record Chunk(String id, String sourceId, String heading, String text) {}\n// Example: one acceptance-criteria section per chunk, preserving its ID.', 'Data shape for traceable chunks; splitter implementation required.', 'SourceId original requirement link karta hai. Heading disambiguate karta hai. Exact citations stable chunk/version identity need karti hain. Test questions across section boundaries include karo.', 'Fixed character split sentences/code midway cut kar sakta hai. Chunk count increase alone retrieval improve nahi guarantee.', 'Versioned source > Coherent section split > Traceable chunks'),
('Embeddings', 'QA knowledge corpus aur query embeddings compatible model se generate karo. Vector dimension/model version metadata maintain karo. Exact IDs/search terms semantic search se miss ho sakte hain; hybrid retrieval useful ho sakti hai. Similarity ranking test expected evidence se evaluate karo rather than plausible prose.', '// Index compatibility metadata:\nrecord EmbeddingConfig(String modelId, int dimensions, String corpusVersion) {}\n// Query embeddings must match the index model/dimensions.', 'Metadata represents compatibility requirements; does not call an embedding service.', 'Model migration old/new index semantics change karti hai. Corpus reindex planned ho. Store filtering access rules enforce karti hai. Similar wording contradictory requirement bhi ho sakti hai.', 'Cosine similarity truth score nahi. Different models same dimensions hon tab bhi spaces compatible necessarily nahi.', 'Corpus + query text > Same model space > Ranked semantic matches'),
('Retrieval', 'Retrieval needed evidence select karti hai. Keyword search exact error/requirement ID match; semantic search paraphrase match; metadata filters version/permissions constrain karti hain. Hybrid reranking improve kar sakti hai but measured evidence recall important hai. Top-k irrelevant chunks prompt filling source confidence create kar sakti hain.', '// Evaluation item:\nrecord RetrievalCase(String question, java.util.Set<String> expectedSourceIds) {}\n// Compare returned source IDs to expected IDs at chosen top-k.', 'A repeatable retrieval benchmark can measure relevant-source recall.', 'Expected sources human-reviewed ground truth hain. Query realistic office/QA wording include kare. Access-denied documents must absent rahen even highly similar. Empty-result path intentional hai.', 'Nearest documents always relevant nahi. Latest requirement version and obsolete versions explicitly distinguish karo.', 'Question + scope filters > Search / rerank > Relevant evidence set'),
('Grounding', 'Grounding answer claims ko actual supplied sources se support karna hai. Citation link present hona claim supported hone ke equal nahi. Model ko insufficient/conflicting evidence report karna chahiye. Version-sensitive requirements latest approved source identify karein. QA generated test expected result cited acceptance criterion se match check kare.', '// Claim evidence shape:\nrecord SupportedClaim(String text, java.util.List<String> sourceIds) {}\n// Verify source IDs were retrieved and source text supports the claim.', 'Validation policy checks references and substantive claim support.', 'Source ID membership structural check hai; semantic support stronger evaluation need karti hai. Contradictory sources escalate/explain rather than silently merge. Quote only relevant allowed excerpts.', 'Invented citation IDs trust illusion create karti hain. Grounding model output ka factual check hai, stylistic confidence nahi.', 'Generated claim > Actual supporting source > Verified / insufficient evidence'),
('MCP Basics', 'MCP clients aur servers ke beech capabilities exchange ka protocol hai. Host user application hai; client server connection manage karta hai; server tools/resources expose karta hai. RAG knowledge retrieval approach hai, MCP integration protocol; dono combine ho sakte hain. Permission execution-level authorize honi chahiye.', '// Architecture sketch:\n// QA host -> MCP client -> approved test-results server\n// Server exposes read_test_result(runId) as a structured tool.', 'Protocol sketch; no MCP server/client starts here.', 'Tool discovery available operations describe karti hai. Client structured call exchange karta hai. Host policy operation scope control karti hai. Authentication/access setup actual server integration ka part hai.', 'MCP connected hona unrestricted repository/production access imply nahi. Retrieved text trusted instructions nahi.', 'QA host > MCP client connection > Capability server'),
('MCP Tools', 'MCP tool named operation with input schema aur output format expose karti hai. Schema arguments validate karne mein help karti hai, permission policy separate enforce hoti hai. Read test result low-impact operation ho sakti hai; merge/deploy state change require explicit authority. Tool failure/result provenance clearly propagate karo.', '// Illustrative tool call shape (not full JSON-RPC envelope):\n{ "name": "read_test_result", "arguments": { "runId": "RUN-42" } }', 'Server validates runId and caller scope, then returns the permitted result.', 'Structured arguments shell text se safer constrained contract enable karte hain. Server checks resource authorization. Error response missing/denied state clearly distinguish kar sakti hai while respecting privacy.', 'Tool annotations/hints alone actual access enforcement nahi. Input text command injection prevent application implementation kare.', 'Typed tool request > Validation + authorization > Result / controlled error'),
('AI Test Generation', 'AI generated tests drafts hain. Acceptance criteria, current code conventions aur existing coverage supply karo. Proposed scenario correct requirement assert kare, mock-only implementation echo nahi. Compile/execution isolation, meaningful review aur duplicate-gap checks needed hain. QA agent effort reduce kar sakti hai but pass rate useful coverage guarantee nahi.', '// Generation checklist:\n// Requirement: reject amount <= 0\n// Draft cases: -1, 0, 1\n// Assert rejection leaves persisted balance unchanged\n// Compile, execute and review before accepting.', 'Concrete test-plan sketch; test code must use the actual application contract.', 'Boundary cases criterion se derive hote hain. State assertion false-success catch karti hai. Real code/tests retrieval project fit improve karti hai. Generated tests can encode incorrect assumptions.', 'Generated test passing does not prove assertion represents requirement. Do not auto-approve based only on green run.', 'Requirements + existing tests > Draft meaningful cases > Execute + review'),
('Failure Analysis', 'AI failure analysis observations aur hypotheses separate kare. Assertion diff, logs, recent changes aur environment versions collect karo. Suspected root cause reproducible experiment se verify karo before code fix. RAG related prior incidents supply kar sakti hai, but similar error actual same cause prove nahi.', 'record FailureEvidence(String assertionDiff, String logs, String commitId) {}\n// Observation: expected 400, actual 200\n// Hypothesis: validation not invoked\n// Check: verify DTO constraint, @Valid and validation dependency.', 'Investigation plan links a concrete failure to verifiable checks.', 'Expected/actual known fact hai. Missing validation hypothesis testable hai. Direct service guard aur HTTP binding checks distinguish possible causes. Environment dependency mismatch separately inspect karo.', 'First plausible AI explanation ko root cause label mat karo. Flaky run retry success underlying defect close nahi karta.', 'Observed failure > Testable hypothesis > Verified cause / next experiment'),
('Evaluation & Guardrails', 'Evaluation representative fixed cases par retrieval, groundedness aur task usefulness measure karti hai. Guardrails permission/schema limits execution boundary par enforce karti hain. Include missing evidence, malicious source instructions, wrong tenant aur tool side-effect cases. Regression dataset version karo to changes compare ho sakein. Model-only self-score enough nahi.', '// Evaluation dimensions:\n// required source retrieved?\n// claim supported?\n// generated test catches intended defect?\n// denied operation remained denied?\n// cost and latency within budget?', 'Reviewed evidence and execution checks produce comparable evaluation results.', 'Positive cases utility measure karte hain; negative/adversarial cases boundary failures detect karte hain. Mutation-style checks generated assertion meaningfulness test kar sakti hain. Track changes per model/prompt/index version.', 'Generic safety prompt actual authorization checks replace nahi karta. High average accuracy rare severe failures hide kar sakti hai.', 'Versioned evaluation cases > Evidence + execution checks > Measured quality / enforced limits'),
])

add(21, [
('Microservice Basics', 'Microservice independently deployable business capability boundary hai. Separate process/network failure design ka part hai. Monolith ko every class separate service banane se complexity badhti hai. Data ownership, API contracts aur deployment independence first clarify karo. QA local behavior aur inter-service compatibility separately verify kare.', '// Payment service HTTP contract\n// POST /payments -> accepted payment ID\n// Booking service consumes PaymentAccepted event\n// Each service owns its persistent state.', 'Architecture sketch; no service starts from these comments.', 'Payment acceptance aur booking different lifecycle ho sakte hain. Distributed eventual consistency user-visible status define karni chahiye. Contract and failure-state tests network dependencies cover karein.', 'More services automatically scalable/better nahi. Shared database tightly coupled deployment boundaries bana sakti hai.', 'Payment capability > API / event boundary > Booking capability'),
('Service Boundaries', 'Boundary business ownership se choose karo, CRUD entity count se nahi. Payment service transaction intent own kar sakti hai; notification service delivery own kare. Shared invariants within one transaction rakhna useful ho sakta hai. Split ke baad latency/failure/consistency costs explicit hain. QA who owns status transition document kare.', '// Payment API returns domain status:\nrecord PaymentResponse(String id, String status) {}\n// Notification API returns delivery status separately:\nrecord DeliveryResponse(String paymentId, String deliveryStatus) {}', 'Separate response contracts prevent payment status and delivery status conflation.', 'Each contract one capability observe karta hai. Notification failure necessarily payment rollback nahi. Consistency policy acceptance criteria mein define karo.', 'Database tables ko arbitrary one-service-per-table split mat karo. Distributed join/transaction overhead evaluate karo.', 'Payment owner > Published domain contract > Notification owner'),
('REST Communication', 'Synchronous REST caller downstream response wait karta hai. Connect/read/request timeout configure karo, status/body interpret karo aur request identity carry karo. Network failure ambiguous ho sakti hai: server processed request but response lost. Side-effect retries idempotency contract ke saath honi chahiye.', 'var request = java.net.http.HttpRequest.newBuilder(java.net.URI.create("http://localhost:9090/status/P1"))\n    .timeout(java.time.Duration.ofSeconds(2)).GET().build();\nvar response = client.send(request, java.net.http.HttpResponse.BodyHandlers.ofString());', 'Needs configured HttpClient and reachable local service; inspect statusCode and body.', 'Caller creates bounded GET then sends. Transport errors aur HTTP503 distinct paths hain. Correlation identifier logs connect karne mein help karta hai.', 'POST blindly retry karna duplicate payment la sakta hai. Timeout total operation cancellation guarantee nahi.', 'Upstream request > Bounded downstream call > Response / failure policy'),
('OpenFeign/WebClient', 'OpenFeign declarative client interface se blocking HTTP calls simplify karti hai; WebClient reactive client pipeline provide karta hai. Runtime dependencies/version-aligned Spring Cloud BOM needed ho sakta hai. Both contract, serialization, timeout aur failure handling need karte hain. Reactive code mein blocking callers carefully isolate karo.', 'WebClient client = WebClient.builder().baseUrl("http://localhost:9090").build();\nreactor.core.publisher.Mono<String> result = client.get().uri("/status/P1")\n    .retrieve().bodyToMono(String.class);', 'Deferred response publisher; request runs when subscribed.', 'retrieve response handling configure karta hai. bodyToMono conversion define karti hai. Publisher declaration alone completed response nahi; caller compose/subscribe lifecycle manage kare.', 'WebClient use karna whole application nonblocking prove nahi. block event-loop thread par harmful ho sakta hai.', 'Typed / fluent client > HTTP transport > Response mapping'),
('Resilience4j', 'Resilience policies downstream failure ka bounded impact define karti hain. Circuit breaker observed failures par calls reject kar sakta hai; retry transient attempts repeat karti hai; bulkhead capacity isolate karta hai. Timeout/retry budgets combine karo to latency explosion avoid ho. Fallback truthful degraded result de, fake success nahi.', 'var breaker = io.github.resilience4j.circuitbreaker.CircuitBreaker.ofDefaults("gateway");\njava.util.function.Supplier<String> protectedCall =\n    io.github.resilience4j.circuitbreaker.CircuitBreaker.decorateSupplier(breaker, () -> gateway.status());', 'Invocation protectedCall.get() applies breaker behavior to a supplied gateway call.', 'Decorator execution boundary intercept karta hai. Config failure thresholds/minimum calls behavior determine karte hain. Open state actual underlying gateway invocation skip karti hai.', 'Circuit breaker remote side effect undo nahi karta. Layered retries multiply attempts; idempotency and budget verify karo.', 'Call budget > Breaker / retry policy > Real result or explicit failure'),
('Config', 'Microservice config environment-specific endpoint/limits ko build artifact se separate rakhti hai. Central config service optional pattern hai, mandatory nahi. Startup required config validation helpful hai. Dynamic change consistency, secret rotation aur fallback availability design require karti hai. QA missing, malformed aur overridden values exercise kare.', '# application.properties\ngateway.url=${GATEWAY_URL:http://localhost:9090}\ngateway.timeout=2s', 'Environment GATEWAY_URL overrides the local default when binding is configured.', 'Placeholder external value choose karta hai, default local development help karta hai. Typed properties validation actual consumer values check kar sakti hai.', 'Production silently localhost fallback dangerous ho sakti hai. Secrets logs/config endpoints mein leak mat karo.', 'Environment config > Bind / validate > Service connection policy'),
('Service Discovery', 'Discovery service logical name ko available network instances se resolve karti hai. Registry patterns aur platform DNS both possible hain. Instance health/staleness/load-balancing behavior caller failure policy se interact karti hai. Fixed local URLs small setups mein fine hain; distributed address changes discovery useful banati hain.', '// Platform DNS example:\nString baseUrl = "http://payment-service:8080";\n// The platform must resolve this name to reachable service instances.', 'Works only in an environment configuring payment-service name resolution.', 'Logical name deploy-specific address hide karta hai. DNS/registry resolution destination choose karti hai, business readiness guarantee nahi. Test vanished instance and stale address.', 'Discovery network calls ko infallible nahi banati. Local machine this hostname automatically resolve nahi karegi.', 'Logical service name > Registry / DNS resolution > Reachable instance'),
('API Gateway', 'API gateway external requests ko backend routes tak map karti hai. Authentication, rate limiting aur routing common concerns hain; business rules owned service mein retain karo. Gateway path/header transformations compatibility affect karti hain. QA gateway plus direct service contracts separately check kar sakti hai.', '# Conceptual route, platform syntax varies:\n# /api/payments/** -> payment-service\n# /api/reports/**  -> report-service\n# Authenticate requests before forwarding.', 'Routing sketch; use your gateway framework configuration for executable routes.', 'Gateway public entry boundary hai. Routing target and stripped/preserved prefix explicit define karo. Auth forwarding trusted identity policy follow kare, arbitrary user header trust nahi.', 'Gateway single dependency bottleneck ho sakti hai. Direct internal access permissions gateway policy bypass na karein.', 'External client > Auth + routing gateway > Owned backend service'),
('Observability', 'Observability logs, metrics aur traces se system behavior infer karne ki capability hai. Logs events, metrics numeric trends aur traces request spans relate karte hain. Payment ID/correlation field useful hai but sensitive data omit karo. QA failure injection ke baad diagnostics cause localize kar paati hain ya nahi verify kare.', '// Structured logging idea:\nlog.info("payment_processed id={} outcome={}", paymentId, outcome);\n// Counter label should be low-cardinality, e.g. outcome=approved/rejected.', 'Useful correlated event; requires configured logging/metrics libraries.', 'Parameterized log context add karta hai. Metrics outcome label bounded values maintain karta hai. High-cardinality user/payment IDs metrics tags mein storage explode kar sakte hain.', 'Verbose logs accurate telemetry guarantee nahi. Sampling and missing instrumentation incomplete picture de sakti hain.', 'System events > Logs / metrics / traces > Diagnosis'),
('Distributed Tracing', 'Trace cross-service request path correlate karti hai. Each span operation timing/status record karta hai; context propagation downstream spans link karti hai. Asynchronous messaging context explicitly carry kar sakti hai. Trace ID business ID nahi. QA known failure call ka path/latency inspect karke propagation gaps detect kar sakti hai.', '// Illustrative HTTP propagation header:\n// traceparent: 00-<32 hex trace id>-<16 hex span id>-01\n// Configure supported tracing instrumentation; do not invent IDs per hop.', 'Related spans share a trace when propagation and instrumentation are configured.', 'Trace context parent-child relationships retain karta hai. Sampled request exported backend mein visible ho sakti hai. Header comment alone instrumentation implement nahi karta.', 'Every log line trace export proof nahi. Async boundary context loss common diagnosis gap hai.', 'Incoming trace context > Service span > Downstream child span'),
('Contract Testing', 'Microservice contract verification independent deployment risk reduce karti hai. Consumer old version aur provider new version compatibility matrix test karo. Schema field add generally less disruptive ho sakta hai than remove/type change, but consumer parsing behavior matters. Provider state must represent meaningful actual behavior.', '// Consumer expects:\n// GET /payments/P1 -> 200\n// id: string, status: one of accepted domain states\n// Provider verifies contract before publishing a compatible version.', 'Compatibility verified only after actual provider contract checks succeed.', 'Required fields and allowed states encode consumer usage. Verification can catch renamed status, wrong type or missing path before deploy. E2E remains useful for cross-service business flow.', 'Two services both using same unverified fake compatibility prove nahi karte. Generated SDK alone provider correctness ensure nahi karti.', 'Consumer usage > Compatibility contract > New provider verification'),
])

add(22, [
('Kafka Basics', 'Kafka append-only partitioned event log provide karta hai. Topic partitions mein records ordered hote hain; whole topic global order guarantee nahi. Producers publish, consumers read offsets track karte hain. Retention consumer read se independently configure hoti hai. QA ordering scope, replay aur failure recovery verify kare.', '// Event contract illustration:\nrecord PaymentAccepted(String eventId, String paymentId, int amount) {}\n// Publish to payments with paymentId as the key.', 'Contract sketch; Kafka broker and producer implementation still required.', 'Stable key same partition ordering strategy support karta hai under configured partitioner. Event ID deduplication identity supply kar sakta hai. Schema evolution contracts define karo.', 'Message consumed means log record deleted nahi. Topic-wide exact global order assume mat karo.', 'Producer event > Partitioned topic log > Consumer offsets'),
('Producer', 'Producer topic/key/value record publish karta hai. Send asynchronous completion return kar sakta hai; acknowledgement result inspect karo. Key partition assignment/order influence karti hai. Serializer payload bytes define karta hai. Producer idempotence transport duplicates reduce kar sakti hai but business side-effect deduplication separate concern hai.', 'var record = new org.apache.kafka.clients.producer.ProducerRecord<String, String>("payments", "P1", "accepted");\nproducer.send(record, (metadata, error) -> {\n    if (error != null) log.error("Publish failed", error);\n});', 'Configured producer eventually acknowledges metadata or reports an error.', 'send initiation success callback success ke equal nahi. Serializer/config/broker needed hain. Application delivery guarantees error/retry/outbox policy se define kare.', 'Ignoring send failures lost events hide kar sakta hai. DB commit plus publish dual-write problem require explicit strategy.', 'Serialize keyed record > Broker append > Acknowledgement'),
('Consumer', 'Consumer poll se records receive karta hai aur processing progress offsets se track hoti hai. Processing before/after commit failure paths duplicate ya loss risks differ karte hain. Consumer thread ownership API contract follow karo. Graceful shutdown and rebalance behavior manage karo. Domain processing idempotent design helpful hai.', 'consumer.subscribe(java.util.List.of("payments"));\nvar records = consumer.poll(java.time.Duration.ofMillis(500));\nfor (var record : records) process(record.value());\n// Commit strategy is deliberately configured separately.', 'Processes records returned by a configured consumer/broker.', 'Subscribe group membership start karta hai. poll assignment/data fetch participate karti hai. process failure offsets policy determine karegi next retry/replay. Empty poll valid hai.', 'Commit before success business work lose kar sakta hai; commit after success crash duplicates possible hain.', 'Poll records > Process business effect > Commit progress policy'),
('Consumer Groups', 'Group related consumers ko partitions distribute karta hai. One partition normally one active consumer within a group assigned hoti hai; different groups independently topic consume kar sakte hain. Extra consumers beyond partitions idle ho sakte hain. Rebalance ownership change karti hai; in-flight state safely handle karo.', '# Consumer configuration idea:\ngroup.id=booking-service\n# A separate analytics group sees its own progress.\n# Parallel useful consumers are bounded by assigned partitions.', 'Group members share partition work; separate groups retain separate offsets.', 'Same group ID competing workers distribute records, broadcast nahi. Analytics different ID se same events independently read kar sakti hai. Partition count concurrency upper bound influence karti hai.', 'Every replica ko unique group ID dene se each all data consume karega, accidental duplicate business processing possible hai.', 'Topic partitions > Group assignment > Independent group progress'),
('Offsets', 'Offset partition-local record position hai. Committed offset generally next record to read represent karta hai. Per-partition progress group ownership se associated hai. Retention purane records remove kar sakti hai, so stored offset available range se outside ho sakta hai. Replay business effect policies ke saath plan karo.', '// Record at offset 10 processed successfully:\n// commit the NEXT offset, 11, for that partition.\n// Offset values are not global across the topic.', 'Consumer resumes from configured committed progress when available.', 'Offset 11 commit means through10 processed policy claim hai. Crash before commit10 again deliver ho sakta hai. Reset earliest retention start se read karta hai, all historical data always nahi.', 'Offset commit actual business DB commit ka proof nahi. Topic partitions offsets compare karke global time/order infer mat karo.', 'Read offset 10 > Process record > Commit next offset 11'),
('Retries', 'Retry transient processing failure ko another attempt deta hai. Bounded attempts, delay/backoff aur failure classification define karo. Permanent invalid event endless retry poison-pill bana sakta hai. Retry topics throughput improve kar sakti hain but partition ordering semantics change kar sakti hain. QA duplicate delivery plus exhaustion cover kare.', 'int maxAttempts = 3;\n// For each attempt: process, retry only transient failures.\n// After exhaustion: record failure and follow DLQ policy.\n// Use stable eventId across attempts.', 'Policy sketch; retry execution and storage must be implemented/configured.', 'Same event identity attempts relate karti hai. Non-retryable schema error immediate terminal path deserve kar sakti hai. Full retry budget latency expectation se align karo.', 'Immediate unbounded retry resource pressure multiply karti hai. Side effects retry-safe design without duplicate transactions required hai.', 'Transient failure > Bounded backoff retry > Success or terminal policy'),
('DLQ', 'Dead-letter destination repeatedly failed ya non-processable events separate karti hai. Preserve original event, source topic/partition/offset aur error context. DLQ monitoring, access policy aur repair/replay procedure chahiye; sirf move karna issue solve nahi. Sensitive payload retention/privacy requirements apply karti hain.', '// Failure envelope illustration:\nrecord DeadLetter(String eventId, String sourceTopic, long sourceOffset, String reason) {}\n// Preserve enough context to diagnose and safely replay.', 'Envelope describes diagnostic context; actual DLQ publish and verification required.', 'Terminal failure original identity se linked rehti hai. Replay same event ID deduplication preserve kare. DLQ publish failure itself operational policy require karti hai.', 'DLQ automatic exactly-once guarantee nahi. Unreviewed replay duplicate or obsolete business effects create kar sakta hai.', 'Exhausted failure > Diagnostic DLQ > Controlled repair / replay'),
('Idempotency', 'Idempotent operation same logical request repeat hone par extra effect avoid karti hai. Stable event/request ID aur durable uniqueness constraint common tools hain. Processed-event insert aur business update same DB transaction mein combine karna atomicity preserve kar sakta hai. In-memory Set multi-instance crash recovery solve nahi karta.', '-- Conceptual schema constraint:\nCREATE TABLE processed_events (event_id VARCHAR(100) PRIMARY KEY);\n-- In one transaction: register event ID and apply its business update.', 'Duplicate ID is rejected by the database uniqueness rule; handling must map to no repeated effect.', 'Unique constraint concurrent same-event races constrain karti hai. Rollback both marker/effect together on failure. Existing ID requires policy already-applied result return karne ka.', 'Check-then-insert alone race-safe nahi. Producer idempotence DB side-effect idempotency replace nahi karti.', 'Stable event ID > Atomic dedupe + effect > Repeat produces no extra effect'),
('Testing Kafka', 'Kafka tests schema/unit serialization, broker integration aur domain consumer behavior different layers cover karti hain. Real disposable broker partition/offset semantics verify karti hai. Poll assertions bounded eventual waiting use karein, fixed sleep nahi. Test group IDs/topics isolation avoid previous-run records interference.', '// Integration-test outline:\n// 1. Start a compatible Kafka Testcontainer.\n// 2. Create unique topic and group.\n// 3. Publish keyed event and await acknowledgement.\n// 4. Await expected persisted effect within a bounded deadline.', 'Requires actual broker integration setup; no broker launched by this outline.', 'Acknowledgement publication establish karti hai; eventual assertion consumer business work observe karti hai. Duplicate event/failure cases include karo. Container class/image version match current library docs.', 'Green mocked KafkaTemplate test broker behavior cover nahi karti. Arbitrary sleep flakes under slow CI.', 'Real test broker > Publish + consume > Bounded effect assertion'),
])

add(19, [
('Boot Project Structure', 'Boot app main class root package mein rakho, so subpackages scan ho sakein. Maven main Java sources src/main/java, resources src/main/resources aur tests src/test/java mein hain. Starter dependencies web, validation aur test capabilities add karti hain. Structure code responsibilities clear karta hai; empty folders alone architecture nahi banati.', '@org.springframework.boot.autoconfigure.SpringBootApplication\npublic class LabApplication {\n    public static void main(String[] args) {\n        org.springframework.boot.SpringApplication.run(LabApplication.class, args);\n    }\n}', 'Starts a Boot app when dependencies and configuration are supplied.', 'Entry annotation configuration/auto-configuration/scanning combine karti hai. run context build karta hai; web starter ho to embedded server start ho sakta hai. Chapter workshop supplies Maven project setup.', 'Main class service/controller package se below ho to scan miss ho sakta hai. Boot 3.5 snippets ko Boot4 imports se randomly mix mat karo.', 'Maven source folders > Root application class > Scanned controller / service'),
('REST Controller', 'REST controller HTTP input ko application call aur response body mein map karta hai. @RestController response-body behavior enable karti hai. PathVariable URL segment, RequestParam query aur RequestBody JSON payload read karta hai. DTO contract choose karo; entity directly expose karna persistence details leak kar sakta hai.', '@RestController\n@RequestMapping("/payments")\nclass PaymentController {\n    @GetMapping("/{id}")\n    java.util.Map<String, String> get(@PathVariable("id") String id) {\n        return java.util.Map.of("id", id);\n    }\n}', 'GET /payments/P1 returns JSON {"id":"P1"}.', 'Class mapping prefix aur method mapping combine hote hain. Explicit path-variable name compiler parameter metadata reliance reduce karta hai. Return map JSON serialize hoti hai with configured web stack.', 'Controller mein every business/database rule combine mat karo. HTTP status and error body consistent contract chahiye.', 'HTTP path P1 > Controller parameter > JSON response'),
('Service Layer', 'Service application rules aur orchestration own karti hai. Controller transport handle kare, repository persistence aur gateway external call. Service plain Java object ki tarah testable reh sakti hai even @Service registered ho. Required invariants UI validation bypass hone par bhi enforce karo.', '@Service\nclass AmountService {\n    int fee(int amount) {\n        if (amount <= 0) throw new IllegalArgumentException("amount");\n        return amount >= 1000 ? 10 : 5;\n    }\n}', 'fee(1000) returns 10; fee(0) rejects input.', 'Service threshold business rule encode karti hai. Test999/1000 and invalid0 boundaries. @Service managed registration ke liye hai, direct new AmountService unit test bhi possible hai.', 'Service method ko HTTP ResponseEntity ke saath tightly couple karna plain domain reuse complicate kar sakta hai.', 'Controller input > Service invariant + rule > Domain result'),
('Validation', 'Bean Validation structural input constraints declare karti hai. @Valid request DTO validation trigger karti hai; @NotBlank empty/whitespace reject aur @Positive numeric positive check karti hai. spring-boot-starter-validation dependency required hai. Business-specific rules service boundary mein separately enforce karo.', 'record CreatePayment(@jakarta.validation.constraints.NotBlank String id,\n                     @jakarta.validation.constraints.Positive int amount) {}\n// Controller signature:\n// void create(@Valid @RequestBody CreatePayment request)', 'Blank id or amount <= 0 produces validation failure when MVC validation is active.', 'DTO annotations constraint metadata hain. @Valid invocation validation run karti hai. JSON parsing failures constraint failure se different stage hain. Nested DTO validation cascading explicit chahiye.', 'Only DTO annotations with no validator/trigger checks perform nahi karti. Nullable boxed values ke liye @Positive alone null reject nahi karta.', 'JSON binding > DTO validation > Service business validation'),
('Exception Handling', 'REST error mapping known failures ko useful HTTP status/body deta hai. @RestControllerAdvice cross-controller handling register karti hai; @ExceptionHandler specific exception choose karta hai. Unexpected bugs internal logging aur sanitized server-error response deserve karte hain. Rejected input ko200 return karna clients confuse karta hai.', '@RestControllerAdvice\nclass ApiErrors {\n    @ExceptionHandler(IllegalArgumentException.class)\n    ResponseEntity<java.util.Map<String, String>> badInput(IllegalArgumentException ex) {\n        return ResponseEntity.badRequest().body(java.util.Map.of("error", "Invalid input"));\n    }\n}', 'Known invalid-input failure maps to HTTP 400 with an error field.', 'Advice context scan hona chahiye. Handler selected exception transform karta hai; response serializer JSON body produce karti hai. Internal exception message expose karna automatically safe nahi.', 'Every exception ko same400 mat map karo. Domain failure aur system failure distinguish karo.', 'Service failure > Advice handler > Consistent HTTP error'),
('Configuration Properties', 'ConfigurationProperties grouped settings ko typed object bind karti hai. URLs, timeout aur limits logical prefix se organize karo. Record/class register karne ke liye scanning ya enable annotation needed hai. Critical settings validation startup misconfiguration jaldi detect karti hai. Environment secret values source code se separate rakho.', '@org.springframework.boot.context.properties.ConfigurationProperties("gateway")\nrecord GatewayProperties(java.net.URI url, java.time.Duration timeout) {}\n// Register with @ConfigurationPropertiesScan\n// application.properties:\n// gateway.url=http://localhost:9090\n// gateway.timeout=2s', 'Bound properties contain a URI and a 2-second Duration.', 'Prefix same group keys match karta hai. Conversion typed Duration/URI banati hai. Registration context object create karti hai, mere annotation on unused record enough nahi.', 'Hardcoded credentials config examples mein reuse mat karo. Missing URL startup validation ya deliberate default require karti hai.', 'External properties > Typed binding > Injected config object'),
('Actuator', 'Actuator operational endpoints health, metrics aur application insight expose karti hai. Starter add karke exposure/security deliberately configure karo. Liveness process recovery aur readiness traffic acceptance different questions hain. Health UP business workflow correctness guarantee nahi. QA healthy, dependency-down aur restricted endpoint access verify kare.', '# application.properties\nmanagement.endpoints.web.exposure.include=health,info\nmanagement.endpoint.health.show-details=never\n# GET /actuator/health', 'With actuator starter, configured endpoint can return {"status":"UP"}.', 'Exposure include visible HTTP endpoints constrain karta hai. Details hide internal sensitive context. Security policy separately apply hoti hai; config no complete auth setup hai.', 'Expose * public internet par accidentally sensitive info leak kar sakta hai. Metrics count business test assertion replace nahi karti.', 'Runtime state > Health indicators > Operational endpoint'),
('Testing Spring Boot', 'Boot tests boundary-specific choose karo: plain service unit, MVC slice, full in-process context ya real server. @WebMvcTest relevant MVC bean graph load karti hai; @SpringBootTest full graph. MockMvc server socket ke bina request handling test karti hai; RANDOM_PORT real HTTP transport add karta hai. External dependencies control karo.', '@SpringBootTest(webEnvironment = SpringBootTest.WebEnvironment.RANDOM_PORT)\nclass HttpTest {\n    @LocalServerPort int port;\n    @Test void serverStarts() { assertTrue(port > 0); }\n}', 'Confirms assigned server port; add actual HTTP/body assertions for endpoint behavior.', 'RANDOM_PORT real server launches on available port. Injected port client base URL banane mein use karo. Start assertion wiring smoke hai, complete endpoint validation nahi. Boot3.5 test imports required hain.', 'Real HTTP request transaction server thread mein run ho sakti hai; test-thread @Transactional rollback all data cover nahi necessarily.', 'Chosen test boundary > Context / server startup > Meaningful behavior assertions'),
])

add(20, [
('JPA Basics', 'JPA object persistence specification hai; Hibernate common provider hai; Spring Data JPA repository convenience layer hai. Entity manager persistence context object state track karta hai. Changes flush SQL mein convert ho sakte hain before commit. ORM SQL behavior hide nahi karta; QA generated queries/constraints observe kare.', '// Within an active EntityManager transaction:\nPayment payment = new Payment("P1");\nentityManager.persist(payment);\nentityManager.flush();', 'Configured provider inserts the new entity when flushed.', 'persist managed state establish karta hai; flush pending persistence operations DB tak synchronize karta hai, transaction commit nahi. Entity mapping and DB required.', 'persist vs merge semantic differences ignore mat karo. In-memory object result actual database commit proof nahi.', 'Entity object > Persistence context > SQL flush / commit'),
('Entities', 'Entity relational row identity/state map karti hai. @Entity registration aur @Id identifier needed hain. JPA entity no-arg constructor public/protected convention/spec requirement follow kare. Object equality, generated IDs aur proxy behavior carefully design karo. Entity lifecycle DTO lifecycle se different hai.', '@jakarta.persistence.Entity\nclass Payment {\n    @jakarta.persistence.Id String id;\n    protected Payment() {}\n    Payment(String id) { this.id = id; }\n}', 'Maps Payment as an entity with application-assigned String ID.', 'Protected no-arg constructor provider instantiate kar sakta hai. Application constructor ID set karti hai. Table naming/config provider convention par depend karti hai; explicit mapping useful ho sakti hai.', 'Entity as public API JSON direct expose relationships/lazy loading surprises de sakta hai. ID uniqueness DB constraint enforce kare.', 'Row identity > Entity mapping > Managed state'),
('Repositories', 'Spring Data repository interface common persistence operations generate/provide karti hai. JpaRepository<Entity,Id> type parameters entity aur identifier match karte hain. Derived finder names property paths se query intent encode karte hain. Return Optional missing entity explicit karta hai. Interface declaration SQL-free business correctness guarantee nahi.', 'interface PaymentRepository extends org.springframework.data.jpa.repository.JpaRepository<Payment, String> {}\n// Service:\nPayment p = repository.findById("P1").orElseThrow(() -> new IllegalArgumentException("missing"));', 'Loads existing P1 or raises the chosen missing-entity failure.', 'Container repository proxy supply karta hai. findById real configured provider call karti hai. Service absence policy define karti hai. Pure mock repository unit test DB mapping validate nahi karta.', 'Repository method runtime generated query errors integration checks deserve karte hain. save result/state semantics new vs existing distinguish karo.', 'Repository interface > Generated implementation > Persistence provider / DB'),
('Relationships', 'JPA associations foreign-key relationships object model mein represent karti hain. ManyToOne common child-to-parent relation hai; bidirectional sides consistency application maintain kare. Owning side database update control karti hai. Fetch/cascade choices lifecycle aur query count affect karte hain. QA missing parent, deletion cascade aur N+1 scenarios verify kare.', '@ManyToOne(fetch = FetchType.LAZY)\n@JoinColumn(name = "customer_id")\nprivate Customer customer;\n// Imports from jakarta.persistence; inside a Payment entity.', 'Payment row references a Customer through customer_id.', 'Join column foreign-key mapping define karti hai. LAZY request provider behavior/transaction context se interact karti hai. Relationship update owning field par apply karo.', 'CascadeType.ALL har relation par blindly data deletion risk la sakta hai. Lazy serialized entity outside context failure de sakti hai.', 'Payment entity > customer_id foreign key > Customer entity'),
('Transactions', 'Spring @Transactional proxy-managed transaction boundary declare karti hai. Public service operation common boundary hai. Default rollback unchecked exceptions/Error par, checked failure policy explicitly configure kar sakte ho. Self-invocation proxy bypass kar sakti hai. Multiple DB changes transactional hain, remote services automatically same ACID unit nahi.', '@org.springframework.transaction.annotation.Transactional\npublic void book(String id) {\n    Payment p = repository.findById(id).orElseThrow();\n    p.markBooked();\n}', 'Managed entity change can be flushed and committed with the service transaction.', 'Caller proxy se service invoke karta hai to interceptor transaction start/joins. Entity mutation persistence context track karti hai. Failure rollback policy test required hai.', 'Same-class method call @Transactional effect assume mat karo. Catch and swallow exception commit allow kar sakta hai.', 'Proxy interception > Service + persistence unit > Commit / rollback'),
('Flyway', 'Flyway ordered versioned SQL migrations se schema evolution track karti hai. V1__create_payments.sql jaise name version/description encode karta hai. Applied migrations history/checksum maintain hoti hai. Applied versioned file edit karne ke bajay new migration add karo. QA empty DB startup aur existing schema upgrade dono test kare.', '-- src/main/resources/db/migration/V1__create_payments.sql\nCREATE TABLE payments (\n    id VARCHAR(50) PRIMARY KEY,\n    amount INTEGER NOT NULL\n);', 'Creates payments table when configured Flyway migration runs against a compatible DB.', 'Naming discovery convention match karti hai. Migration SQL actual schema define karti hai. JDBC driver, Flyway support module/version and DB config needed hain.', 'ddl-auto create/drop production schema migration replacement nahi. Vendor SQL difference realistic DB tests se check karo.', 'Versioned SQL file > Migration history check > Schema evolves'),
('Oracle/PostgreSQL', 'Oracle aur PostgreSQL both relational DB hain but dialect, types, sequence behavior aur transaction features differ karte hain. Local PostgreSQL test fast ho sakta hai, but Oracle production-specific SQL validate nahi necessarily karta. Oracle19 behavior QA appropriate Oracle instance/container/license setup se verify kare. Portable ORM mapping still vendor integration test deserve karti hai.', '-- PostgreSQL connection URL:\n-- jdbc:postgresql://localhost:5432/lab\n-- Oracle service URL:\n-- jdbc:oracle:thin:@//localhost:1521/FREEPDB1', 'Each requires its matching driver, actual service name and credentials.', 'URL syntax connection vendor/service select karti hai. Port/service illustrative hain. Schema casing, null/empty string and pagination differences meaningful compatibility cases hain.', 'Oracle example service FREEPDB1 Oracle19 default guarantee nahi. Use actual DBA-provided service name.', 'Selected DB vendor > Matching driver + dialect > Vendor-realistic validation'),
('Pagination', 'Pagination large result subsets serve karti hai. Page includes content plus counts; Slice can avoid total-count requirement. Spring page indices zero-based hain. Stable sort/tie-breaker results across pages consistent banata hai. Offset pagination concurrent inserts se duplicates/missing rows de sakti hai; keyset strategy alternative hai.', 'var request = org.springframework.data.domain.PageRequest.of(0, 20,\n    org.springframework.data.domain.Sort.by("id"));\nvar page = repository.findAll(request);\nSystem.out.println(page.getNumber());', '0 for requested first page; content depends on DB fixtures.', 'PageRequest first page20 limit aur ID order specify karti hai. Repository query pagination apply karti hai. Test empty, exact20,21 items aur stable ordering.', 'Database natural row order rely mat karo. Huge offsets expensive ho sakte hain; count query load consider karo.', 'Sorted query > Page window 0..19 > Content + metadata'),
])

add(16, [
('JDBC Introduction', 'JDBC Java application ko relational database driver ke through SQL execute karne ka standard API deta hai. Connection session, PreparedStatement query aur ResultSet rows represent karte hain. Driver vendor-specific communication handle karta hai. QA actual persisted rows aur rollback behavior verify kar sakta hai. DB service aur JDBC driver dependencies required hain.', 'try (var connection = dataSource.getConnection();\n     var statement = connection.prepareStatement("select 1");\n     var rows = statement.executeQuery()) {\n    if (rows.next()) System.out.println(rows.getInt(1));\n}', '1 on a configured compatible database; dataSource must be supplied.', 'Connection acquire, SQL prepare aur query execute hoti hai. next cursor first row par move karta hai. getInt(1) first column read karta hai. Resources reverse order close hoti hain.', 'DB-free snippet ko actual JDBC integration test mat label karo. Vendor SQL portability validate karo.', 'Java JDBC API > Vendor driver > Database result rows'),
('JDBC Drivers', 'Driver JDBC calls ko database-specific wire protocol mein translate karta hai. PostgreSQL aur Oracle alag driver artifacts/URLs use karte hain. Modern drivers service discovery se register ho sakte hain; Class.forName every setup mein necessary nahi. Classpath missing aur network/authentication failures separately diagnose karo.', 'String url = "jdbc:postgresql://localhost:5432/lab";\ntry (var c = java.sql.DriverManager.getConnection(url, "lab", "local-password")) {\n    System.out.println(c.isValid(2));\n}', 'true only with reachable DB, correct credentials and PostgreSQL JDBC driver.', 'URL vendor driver choose karne mein help karti hai. Connection requires driver artifact plus external service. isValid timeout seconds mein hai. Demonstration password production secret handling pattern nahi.', 'Driver dependency hona DB running proof nahi. Modern Type4 drivers common hain; historical driver taxonomy runtime setup replace nahi karti.', 'JDBC URL > Matching driver > Database connection'),
('Connection', 'Connection database session aur transaction context expose karti hai. Acquire from DataSource, use bounded scope, close/return to pool. Auto-commit default commonly true hota hai; transaction grouping ke liye explicitly manage karo. Connection generally application-wide shared mutable object ki tarah use nahi karni chahiye.', 'try (var c = dataSource.getConnection()) {\n    System.out.println(c.getAutoCommit());\n    c.setAutoCommit(false);\n    // Execute related statements.\n    c.commit();\n}', 'Prints current auto-commit setting; commits the configured session transaction.', 'DataSource concrete configured dependency hai. Setting false related statements one transaction mein group karti hai. On failure rollback handling required hai; close pool connection return kar sakti hai.', 'Transaction failure catch mein rollback forget mat karo. Pooled state reset library policy verify karo.', 'Acquire session > Execute transaction scope > Commit / rollback then close'),
('Statement vs PreparedStatement', 'Statement raw SQL execute karti hai; PreparedStatement placeholder parameters bind karti hai. User values SQL syntax mein concatenate karna injection risk hai. Parameters values ke liye hain, arbitrary table/column identifiers ke liye nahi. Driver/database preparation strategy vary kar sakti hai; security benefit proper binding se aata hai.', 'try (var ps = connection.prepareStatement("select status from payments where id = ?")) {\n    ps.setString(1, paymentId);\n    try (var rs = ps.executeQuery()) {\n        while (rs.next()) System.out.println(rs.getString("status"));\n    }\n}', 'Prints matching payment status from the configured database.', 'Question mark first positional bind hai; JDBC indices one-based. setString value data ke roop mein supply karti hai. executeQuery returns rows. Dynamic sort column allowed-list se separately choose karo.', 'Quoted placeholder like id = \'?\' bind nahi karta. Entire SQL string ko parameter pass nahi kar sakte.', 'SQL placeholders > Bind input values > Execute safe value query'),
('Transactions', 'Transaction multiple DB changes ko one consistency boundary mein group karti hai. Commit changes finalize karta hai; rollback failed unit revert karti hai. Isolation concurrent visibility influence karti hai. DB transaction network side effects automatically undo nahi karti. QA mid-operation failure inject karke partial persisted state check kare.', 'connection.setAutoCommit(false);\ntry {\n    // Debit and credit on this same connection.\n    connection.commit();\n} catch (java.sql.SQLException ex) {\n    connection.rollback();\n    throw ex;\n}', 'Both DB operations commit together, or the transaction rolls back on SQLException.', 'Same session statements same transaction join karte hain. Catch rollback failure handling production mein consider karo. External HTTP call DB rollback se reverse nahi hoti.', 'Catch-and-swallow failed statement ke baad commit partial data allow kar sakta hai. Auto-commit setting transaction scope affect karti hai.', 'Begin grouped changes > Success commit > Failure rollback'),
('ResultSet', 'ResultSet query rows ka cursor API hai. Initially before-first position hoti hai; next true first/current row establish karta hai. Column name ya one-based index se read karo. SQL NULL primitive getter ke default value se ambiguous ho sakta hai; wasNull ya typed getObject use karo. Resource lifetime connection/statement ownership follow karti hai.', 'try (var rs = statement.executeQuery("select amount from payments")) {\n    while (rs.next()) {\n        Integer amount = rs.getObject("amount", Integer.class);\n        System.out.println(amount);\n    }\n}', 'Prints each amount; SQL NULL can be represented as null.', 'next cursor advance karta hai. Typed getObject compatible DB value return karti hai. Row count aur ordering query contract se determined hain; SQL without order by order guarantee nahi.', 'rs.getInt before next illegal cursor state hai. ResultSet ko closed connection ke baad lazy consume mat karo.', 'Cursor before first > next row > Read columns'),
('Metadata', 'DatabaseMetaData driver/database capabilities describe karti hai; ResultSetMetaData returned columns describe karti hai. Dynamic report/schema diagnostics mein useful hai. Capability metadata aur real behavior verification complement karte hain. Aliased column label aur original column name differ ho sakte hain.', 'var meta = resultSet.getMetaData();\nSystem.out.println(meta.getColumnCount());\nSystem.out.println(meta.getColumnLabel(1));', 'Query-specific column count and first column label.', 'Metadata data rows se separate structure information deti hai. getColumnLabel alias reflect kar sakta hai. Column indices one-based hain; types driver reported SQL/JDBC metadata follow karte hain.', 'Database driver metadata support uniform assume mat karo. Metadata output ko whole business schema validation ka substitute mat banao.', 'Query structure > ResultSetMetaData > Column labels / types'),
('Connection Pooling', 'Pool established sessions reuse karke connection creation cost reduce karta hai. Borrow-use-return lifecycle follow karo; close pooled logical connection generally physical close nahi. Pool capacity database capacity aur workload se align honi chahiye. Acquisition timeout exhaustion detect karne mein useful hai. Leaked connections suite/app hang kar sakti hain.', 'try (var connection = pooledDataSource.getConnection()) {\n    // Execute bounded database work.\n}\n// close returns the logical connection to the pool.', 'Session becomes available for reuse according to pool implementation.', 'Configured pool DataSource interface implement karti hai. Short bounded ownership concurrency easier banati hai. Measure active, idle, pending and timeouts to diagnose resource pressure.', 'Max pool size blindly increase karna database overload la sakta hai. Transaction state reuse reset policy verify karo.', 'Borrow pooled connection > Bounded DB work > Close returns to pool'),
])

add(17, [
('Maven', 'Maven pom.xml project dependencies, plugins aur lifecycle declare karta hai. compile main code, test tests aur package artifact build karta hai. Integration tests Failsafe configuration se verify phase mein run ho sakti hain. QA repeatable command-line build IDE behavior se more authoritative hai. Dependency versions parent/BOM manage kar sakte hain.', 'mvn test\nmvn verify\nmvn dependency:tree', 'Test/build reports depend on the actual project; dependency:tree lists resolved dependencies.', 'test unit test phase execute karta hai. verify configured integration checks include kar sakta hai. dependency tree conflicts/multiple versions inspect karne ke liye hai.', 'test command every integration test automatic nahi chalata. Skip flags green build ko complete validation jaisa show kar sakte hain.', 'pom dependencies > Build lifecycle phases > Test reports + artifact'),
('JUnit 5', 'JUnit Jupiter behavior-focused tests aur lifecycle APIs provide karta hai. Arrange setup, act operation aur assert expectation clear rakho. Parameterized tests boundaries cover karti hain. Expected exception assertThrows se assert karo and state unchanged requirement separately check karo. Test names concrete behavior communicate karein.', '@org.junit.jupiter.api.Test\nvoid rejectsNegativeAmount() {\n    org.junit.jupiter.api.Assertions.assertThrows(IllegalArgumentException.class, () -> new Account(-1));\n}', 'Passes only if Account(-1) throws IllegalArgumentException.', 'Test method Jupiter engine execute karti hai. Lambda exception action defer karti hai. JUnit dependency and compatible Account constructor required hain. Test isolated class contract verify karta hai.', 'Assertion absent test normally pass kar sakta hai despite incorrect behavior. assertThrows supertype match consider karo if exact type important hai.', 'Arrange input > Act constructor > Assert rejected contract'),
('Mockito', 'Mockito collaborator doubles provide karta hai: stub response aur interaction verify. Object under test actual implementation hona chahiye. Service rule isolate karne ke liye fake/mock gateway useful hai, real Spring context mandatory nahi. Verification actual contract-important side effect par focus kare, every internal call sequence par nahi.', 'Gateway gateway = org.mockito.Mockito.mock(Gateway.class);\norg.mockito.Mockito.when(gateway.pay(100)).thenReturn(true);\nboolean accepted = gateway.pay(100);\norg.junit.jupiter.api.Assertions.assertTrue(accepted);\norg.mockito.Mockito.verify(gateway).pay(100);', 'Stub returns true and verification confirms one matching call.', 'mock Gateway interface double banata hai. when answer configure karti hai. verify observation check karti hai. Real service test mein mock ko service constructor inject karo, only mock behavior test karna enough nahi.', 'Mocked object under test real business implementation cover nahi karta. Unstubbed default responses misleading ho sakte hain.', 'Controlled collaborator > Real service action > Behavior / interaction assertion'),
('REST Assured', 'REST Assured HTTP requests aur response assertions ka DSL hai. Running server/local stub required hai. Status alone enough nahi; meaningful body, headers aur error contract verify karo. Authentication/test-data setup explicit rakho. JSON numeric types assertions mein actual representation se align karein.', 'io.restassured.RestAssured.given()\n    .baseUri("http://localhost:8080")\n.when().get("/payments/P1")\n.then().statusCode(200)\n    .body("id", org.hamcrest.Matchers.equalTo("P1"));', 'Passes if running service returns 200 and JSON id P1.', 'given request setup hai; when call perform karti hai; then expectations check karti hai. Missing server connection failure dega, assertion execution service create nahi karti.', 'Only 200 check incorrect body miss kar sakta hai. Global mutable REST Assured config parallel tests interfere kar sakti hai.', 'Configured HTTP request > Running API > Status + body assertions'),
('TestNG', 'TestNG test framework annotations, groups, dependencies aur data providers supply karta hai. Data provider multiple cases feed kar sakti hai; lifecycle scope method/class/suite clearly choose karo. Selenium suites commonly use it, but JUnit engine annotations interchangeable nahi. Parallel execution fixtures ownership require karti hai.', '@org.testng.annotations.DataProvider\npublic Object[][] amounts() { return new Object[][]{{1}, {100}}; }\n@org.testng.annotations.Test(dataProvider = "amounts")\npublic void acceptsPositive(int amount) {\n    org.testng.Assert.assertTrue(amount > 0);\n}', 'Two cases pass: amounts 1 and 100.', 'Provider rows argument sets hain. TestNG invokes test per row. Real contract test mein service operation bhi execute karo; this snippet provider wiring illustrate karti hai.', 'JUnit @Test TestNG runner mein automatically equivalent nahi. Dependent tests brittle order coupling la sakte hain.', 'DataProvider cases > Test invocation per row > Assertions'),
('Component Testing', 'Component boundary pehle define karo: one backend deployment controller/service/repository plus real DB include kar sakta hai, outside payment service controlled stub ho. UI component rendering/interaction mounted separately test ho sakti hai. Few E2E flows both connect karein. Boundary test ka purpose internal collaboration aur external contract verify karna hai.', '@SpringBootTest\n@AutoConfigureMockMvc\nclass PaymentComponentTest {\n    @Autowired MockMvc mvc;\n    @Test void returnsPayment() throws Exception {\n        mvc.perform(get("/payments/P1")).andExpect(status().isOk());\n    }\n}', 'Requires Boot 3.5 test imports, configured fixture and controlled dependencies.', 'Full application context internal wiring include karta hai. MockMvc HTTP handling in process drive karti hai; no real network socket. Add body/database assertions to verify meaningful behavior, setup P1 beforehand.', 'Mock every internal layer karoge to component collaboration cover nahi hogi. Scope document karo; status-only sample full business validation nahi.', 'API boundary > Real internal layers > Controlled external systems'),
('Contract Testing', 'Contract test consumer/provider compatibility verify karti hai: method/path, schema aur meaningful provider states. Consumer-generated stub useful hai only if provider against same contract verify hua ho. Actual database/business scenarios separate tests deserve karte hain. Additive fields, required fields aur status changes compatibility affect karte hain.', '// Example contract shape, not an executable Pact file:\n// Given: payment P1 exists\n// Request: GET /payments/P1\n// Response: 200, {"id":"P1","status":"BOOKED"}\n// Verify this expectation against the real provider.', 'Provider verification must accept the agreed request/response contract.', 'Provider state deterministic fixture establish karti hai. Consumer expectation schema/matching rules encode karti hai. Verification checks running provider; hand-written stub alone only assumption hai.', 'Consumer stub green result provider compatibility prove nahi karta. Avoid overly exact incidental values in shared contract.', 'Consumer expectation > Shared verified contract > Provider implementation'),
('Testcontainers', 'Testcontainers Docker-backed real disposable dependency start karti hai, in-memory fake nahi. PostgreSQL container actual DB semantics verify karti hai; Oracle-specific behavior ke liye suitable Oracle environment needed hai. Dynamic ports avoid parallel conflicts. Container readiness verify karke migration aur fixture setup karo.', '@org.testcontainers.junit.jupiter.Container\nstatic final org.testcontainers.containers.PostgreSQLContainer<?> db =\n    new org.testcontainers.containers.PostgreSQLContainer<>("postgres:16-alpine");\n// Use db.getJdbcUrl(), getUsername(), getPassword() after startup.', 'JUnit Testcontainers extension + PostgreSQL driver + Docker required.', 'Pinned image DB version repeatable banati hai. @Testcontainers class annotation lifecycle extension enable karti hai. Dynamic URL started container ke mapped port use karti hai.', 'Container declared hona startup extension enabled prove nahi. Image/vendor choice production behavior fidelity affect karta hai.', 'Docker dependency starts > Dynamic DB connection > Real integration assertions'),
])

add(18, [
('Spring Introduction', 'Spring application objects aur cross-cutting concerns organize karta hai. Core container objects create/wire karta hai; MVC, transactions aur testing other capabilities hain. Spring Boot convention/auto-configuration simplify karti hai, core Spring replace nahi. QA boundary isolate kar sakti hai with plain Java tests while wiring context tests verify karte hain.', '@org.springframework.stereotype.Service\nclass PaymentService {\n    String status() { return "READY"; }\n}', 'Service bean is registered when its package is component-scanned.', 'Annotation metadata container registration guide karti hai. new PaymentService plain object create karta hai without scanning/lifecycle/proxies. Boot entry package scope relevant hai.', 'Annotation alone object ko every runtime context mein managed bean nahi banati. Scanning and application setup required hain.', 'Bean metadata > Spring container > Managed service'),
('IoC', 'Inversion of Control object lifecycle/dependency assembly ka control application constructors se container/framework ko move karta hai. Application behavior still your code mein hai. Container definitions se graph create karta hai aur callers ready object receive karte hain. Dependency Injection IoC implement karne ka common mechanism hai.', '@Configuration\nclass AppConfig {\n    @Bean Gateway gateway() { return new FakeGateway(); }\n    @Bean PaymentService service(Gateway gateway) { return new PaymentService(gateway); }\n}', 'Container creates Gateway and injects it into PaymentService.', 'Bean methods configured definitions hain. Container gateway parameter resolve karke service creation karega. Types/annotations require Spring imports and corresponding classes.', 'IoC ka matlab container business rules decide karta hai nahi. Circular graph construction failures dependency design indicate kar sakti hain.', 'Configuration graph > Container assembly > Ready application objects'),
('Dependency Injection', 'Dependency Injection required collaborator externally supply karti hai. Constructor injection dependency explicit aur immutable-reference friendly banati hai. Service ko gateway khud new nahi karna, so QA fake inject kar sakti hai. Framework ke bina plain constructor injection bhi DI hai. Multiple candidate beans qualifier/primary require kar sakte hain.', 'class PaymentService {\n    private final Gateway gateway;\n    PaymentService(Gateway gateway) { this.gateway = java.util.Objects.requireNonNull(gateway); }\n    boolean pay(int amount) { return gateway.pay(amount); }\n}\n// Test setup: new PaymentService(new FakeGateway())', 'Service delegates payment to the injected implementation.', 'Constructor contract collaborator require karta hai. this.gateway same-name field assign karti hai. Test fake network dependency replace karti hai while real service behavior stays executable.', 'Field injection plain unit-test construction less clear banati hai. DI itself missing validation/business correctness solve nahi karti.', 'Real or fake Gateway > Constructor injection > PaymentService delegates'),
('Bean Lifecycle', 'Managed bean creation, dependency population, initialization, use aur destruction stages hain. @PostConstruct initialization callback aur @PreDestroy owned cleanup callback ho sakti hain. Container context close normal managed lifecycle complete karta hai. Prototype destruction automatic same tarah managed nahi. Constructor ideally heavy side effects avoid kare.', '@Component\nclass ClientHolder {\n    @jakarta.annotation.PostConstruct void initialize() { System.out.println("ready"); }\n    @jakarta.annotation.PreDestroy void shutdown() { System.out.println("close"); }\n}', 'ready after managed initialization; close on normal context shutdown for this singleton.', 'Spring registration required hai. Callback dependency injection ke baad initialization point deta hai. Cleanup only owned resources close kare. new ClientHolder callback automatically invoke nahi karta.', 'Crash/forced shutdown cleanup guarantee nahi. Bean constructor mein remote calls context startup fragile bana sakti hain.', 'Create + inject > Initialize callback > Use then destroy'),
('Scopes', 'Bean scope instance lifetime define karti hai. Singleton per bean definition per container common default hai, entire JVM universal singleton nahi. Prototype each retrieval/create request new instance de sakta hai. Web request/session scopes HTTP lifecycle track karti hain. Singleton mutable fields concurrent requests share kar sakti hain.', '@Component\n@org.springframework.context.annotation.Scope("prototype")\nclass TestSession {\n    final java.util.UUID id = java.util.UUID.randomUUID();\n}', 'Two container lookups can create different TestSession instances.', 'Prototype definition new managed instance per lookup create karti hai. Prototype injected once into singleton automatically per-method new instance nahi banati; provider/scoped proxy strategy needed ho sakti hai.', 'Singleton beans automatically thread-safe nahi. Prototype resources cleanup owner ko manage karna pad sakta hai.', 'Scope definition > Container lookup policy > Instance lifetime'),
('Configuration', 'Java configuration @Configuration aur @Bean se managed graph declare karti hai. Externalized properties environment-specific values decouple karti hain. Component scanning automatic discovery alternative/complement hai. Test configuration controlled collaborator provide kar sakti hai; avoid duplicate ambiguous bean registration.', '@Configuration\nclass GatewayConfig {\n    @Bean Gateway gateway() { return new FakeGateway(); }\n}', 'Registers one Gateway bean in a context importing/scanning GatewayConfig.', 'Bean method return type dependency resolution support karta hai. Config class context include honi chahiye. Annotation parameters/imports belong actual Spring project.', 'Config class filesystem mein exist hona auto-import guarantee nahi. proxyBeanMethods setting direct @Bean-method call semantics affect karti hai.', 'Configuration class > Bean definition > Resolvable dependency'),
('Profiles', 'Profiles named environment conditions par bean/config activation select karte hain. local, test, prod naming convention hai, language guarantee nahi. Test profile stub gateway activate kar sakti hai. Profiles secrets management replacement nahi. Active combination behavior aur no-match startup failures verify karo.', '@Configuration\n@org.springframework.context.annotation.Profile("test")\nclass TestGatewayConfig {\n    @Bean Gateway gateway() { return new FakeGateway(); }\n}\n// Test class: @ActiveProfiles("test")', 'Fake Gateway is available only while the test profile is active.', 'Profile condition registration guard hai. @ActiveProfiles test context ko activation supply karti hai. Production candidate overlap ho to explicit condition alignment chahiye.', 'test profile accidentally production activate mat karo. Profile name itself secure boundary nahi.', 'Active profile input > Conditional definitions > Selected bean graph'),
])

add(13, [
('Threads Introduction', 'Thread independent execution path hai, shared process resources ke saath. Runnable task describe karta hai; Thread execution mechanism hai. Concurrency overlapping progress hai, parallelism simultaneous execution. Scheduling nondeterministic hai; output order test fixed assume na kare. I/O waits parallelize karna useful ho sakta hai but shared state coordination chahiye.', 'Thread worker = new Thread(() -> System.out.println("worker"));\nworker.start();\nworker.join();\nSystem.out.println("done");', 'worker\ndone', 'start new execution schedule karta hai. join caller ko worker completion tak wait karata hai, so done afterward print hota hai. join InterruptedException declare/catch chahiye.', 'Thread sleep synchronization proof nahi. Every task ko new raw thread dena resource overhead create karta hai.', 'Runnable task > Worker thread starts > join waits completion'),
('start() vs run()', 'start thread ko schedule karta hai aur JVM new execution path mein run invoke karti hai. Direct run ordinary method call hai current thread mein. Same Thread instance start only once ho sakti hai. QA parallel execution setup mein direct run accidental sequential suite bana sakta hai.', 'Thread t = new Thread(() -> System.out.println(Thread.currentThread().getName()));\nt.run();\nt.start();\nt.join();', 'First line normally main; second line the worker thread name.', 'Direct run caller thread identify karta hai. start real new thread execution deta hai. join observation ordering complete karta hai. Thread name platform/generated settings depend karti hai.', 'run call ke baad thread lifecycle started nahi hoti, but start twice IllegalThreadStateException hai.', 'Direct run: caller > start: new thread > join: completion'),
('Main Thread', 'Traditional main method main thread par start hoti hai. Additional non-daemon threads application ko alive rakh sakti hain even main return kare. Daemon status JVM shutdown rules affect karta hai; critical work ke liye daemon completion assume mat karo. Lifecycle management executor shutdown/join se explicit rakho.', 'System.out.println(Thread.currentThread().getName());\nSystem.out.println(Thread.currentThread().isDaemon());', 'main\nfalse (ordinary launcher context)', 'Current thread main execution context hai. Non-daemon main normal startup behavior hai. Thread naming configurable hai, so application logic name par depend nahi kare.', 'main return means all background work complete nahi. Executor leaks process/test run hang kar sakte hain.', 'Launcher > Main execution > Managed worker lifecycle'),
('Thread Priority', 'Priority scheduler hint hai, portable ordering guarantee nahi. Operating system aur runtime actual behavior influence karte hain. MIN_PRIORITY, NORM_PRIORITY, MAX_PRIORITY conventional constants hain. Business ordering ke liye priority nahi, explicit queues/dependencies use karo. Virtual threads priority behavior platform threads se differ kar sakta hai.', 'Thread t = new Thread(() -> {});\nt.setPriority(Thread.NORM_PRIORITY);\nSystem.out.println(t.getPriority());', '5 for this ordinary platform Thread.', 'Setter allowed priority request karta hai. Getter configured value read karta hai, execution order prove nahi karta. Two tasks priority se deterministic completion sequence expect mat karo.', 'High priority starvation risks solve karne ki reliable cross-platform technique nahi. Tests priorities par timing assertions na karein.', 'Priority hint > Runtime / OS scheduler > No ordering guarantee'),
('Synchronization', 'synchronized same monitor lock par mutually exclusive critical section provide karta hai and visibility relationship establish karta hai. Increment read-modify-write operation hai, plain int++ atomic nahi. Same state protect karne wale all accesses consistent monitor use karein. Different instance locks shared static state protect nahi karte.', 'class Counter {\n    private int value;\n    synchronized void increment() { value++; }\n    synchronized int value() { return value; }\n}', 'After two completed increment calls, value() returns 2.', 'Instance methods receiver monitor lock karti hain. Concurrent increments same object par serialized hote hain. Reader same monitor use karta hai, updated state visible hoti hai.', 'volatile value++ compound operation atomic nahi banata. Long blocking work lock ke andar contention badha sakta hai.', 'Shared counter > Same monitor lock > Atomic update + visibility'),
('Thread Safety', 'Thread-safe component concurrent callers ke saath documented invariants preserve karta hai. Immutability, confinement, locking aur atomic operations different strategies hain. Collection thread-safe hona multi-step workflow atomic guarantee nahi. QA tests useful schedules construct karein; random stress passing mathematical proof nahi.', 'var count = new java.util.concurrent.atomic.AtomicInteger();\ncount.incrementAndGet();\ncount.incrementAndGet();\nSystem.out.println(count.get());', '2', 'AtomicInteger each increment atomically apply karta hai. Several related fields ka invariant one AtomicInteger se solve nahi hota. Immutable fixture per thread shared mutable fixture se easier ho sakti hai.', 'ConcurrentHashMap get-then-put race ko automatically combine nahi karti; compute/putIfAbsent contract consider karo.', 'Concurrent access > Chosen safety strategy > Preserved invariant'),
('Locks', 'Explicit Lock synchronized se extra options deta hai, such as timed acquisition aur interruptible waits. Lock acquire hua to finally mein release karo. Ownership aur scope clear hone chahiye; failing branch lock hold chhod de to workers block ho sakte hain. Shared readers/writers workloads ke liye suitable specialized locks available hain.', 'java.util.concurrent.locks.Lock lock = new java.util.concurrent.locks.ReentrantLock();\nlock.lock();\ntry {\n    System.out.println("protected work");\n} finally {\n    lock.unlock();\n}', 'protected work', 'lock acquisition critical section begin karti hai. finally success/failure dono normal exits par unlock karti hai. Same lock instance shared data protect karni chahiye.', 'Acquisition fail hui ho to unlock blindly mat karo. Lock ko method-local bana kar shared cross-thread state protect nahi hoga.', 'Acquire shared lock > Critical section > finally unlock'),
('ReentrantLock', 'ReentrantLock owning thread ko same lock repeatedly acquire karne deta hai. Har acquisition matching unlock require karti hai. tryLock timed/immediate decision de sakta hai, useful bounded waiting mein. Fair mode ordering policy tradeoff deta hai, complete thread scheduling fairness nahi. Most simple exclusive sections synchronized se clearer ho sakte hain.', 'var lock = new java.util.concurrent.locks.ReentrantLock();\nif (lock.tryLock()) {\n    try { System.out.println("acquired"); }\n    finally { lock.unlock(); }\n}', 'acquired when uncontended.', 'tryLock acquisition success boolean deta hai. Work only success branch mein execute hota hai, so finally unlock legal hai. Failed acquisition ke liye caller retry/failure policy define kare.', 'Repeated acquisition ka hold count zero hone tak release incomplete hai. Fairness higher throughput guarantee nahi.', 'tryLock attempt > Success owns lock > Balanced unlock'),
('Deadlock', 'Deadlock circular waiting hai: thread A lock1 hold karke lock2 wait kare, B lock2 hold karke lock1 wait kare. Consistent global lock order cycle prevent karne ka common approach hai. Diagnostic thread dump owners/waits show kar sakta hai. Fix sleep add karna nahi; ownership/dependency design change chahiye.', 'Object first = new Object();\nObject second = new Object();\n// Every caller follows the same order:\nsynchronized (first) {\n    synchronized (second) { System.out.println("work"); }\n}', 'work; consistent shared lock order avoids this two-lock cycle.', 'All operations first then second lock karein to opposite-order cycle unavailable hai. Objects must be same shared locks. Example deadlock deliberately trigger nahi karta.', 'Different code paths opposite order use karein to prevention fail. Timeout diagnosis aur recovery semantics separately design karo.', 'Thread A holds first > Both request same order > No reverse waiting cycle'),
('Thread Pools', 'ExecutorService bounded worker reuse aur task lifecycle manage karta hai. Pool size workload aur resource capacity se choose karo. Fixed thread pool queue unbounded ho sakti hai, so producer rate/backpressure consider karo. shutdown new tasks stop accept karta hai; awaitTermination completed shutdown wait kar sakta hai.', 'var pool = java.util.concurrent.Executors.newFixedThreadPool(2);\ntry {\n    var result = pool.submit(() -> 42);\n    System.out.println(result.get());\n} finally { pool.shutdown(); }', '42', 'submit Future result deta hai. get result readiness wait karta hai and checked failures handle/declare chahiye. Finally executor lifecycle end initiate karta hai.', 'Pool shutdown forget karna tests hang kar sakta hai. Worker ke andar same saturated pool ka nested task wait starvation deadlock la sakta hai.', 'Submit tasks > Reused pool workers > Future result + shutdown'),
('CompletableFuture', 'CompletableFuture asynchronous completion stages compose karti hai. thenApply value transform karta hai; thenCompose nested asynchronous work flatten karta hai; allOf completion combine karta hai. Exceptions completion chain mein propagate hoti hain. Default async pool shared ho sakta hai; blocking I/O ke liye explicit executor policy useful hai.', 'var future = java.util.concurrent.CompletableFuture.completedFuture(20)\n    .thenApply(n -> n + 2)\n    .thenApply(n -> n * 2);\nSystem.out.println(future.join());', '44', 'Completed future 20 provide karti hai. Transformations sequential dependency se 22 then44 banati hain. This snippet async thread launch prove nahi karta; completed stages inline execute ho sakti hain.', 'join failure CompletionException wrap kar sakta hai. Every thenApply automatically different thread mein nahi chalti.', 'Completion value 20 > Transform 22 > Transform 44'),
])

add(14, [
('Java IO', 'Java IO external data streams/files se connect karti hai. Byte streams binary content ke liye; character Readers/Writers encoded text ke liye. Encoding explicitly choose karo to OS defaults se tests unstable na hon. Resource open/close ownership aur exceptions critical hain. Small fixture Files helpers se simpler ho sakti hai.', 'var path = java.nio.file.Path.of("report.txt");\njava.nio.file.Files.writeString(path, "PASS", java.nio.charset.StandardCharsets.UTF_8);\nSystem.out.println(java.nio.file.Files.readString(path));', 'PASS (creates/replaces report.txt in the current directory).', 'Path destination represent karta hai. writeString text encode+write+close karti hai; readString result return karti hai. IOException handle/declare chahiye. Controlled temp directory in tests better hai.', 'Binary bytes ko arbitrary character reader se decode mat karo. Relative path working directory par depend karti hai.', 'Text value > UTF-8 bytes file > Decoded text'),
('Reader', 'Reader character input abstraction hai. read integer character code ya -1 end-of-input deta hai. Character decoding byte stream par charset apply karti hai. StringReader in-memory text parsing tests ke liye useful hai; file reader actual external resource hai. Buffering many tiny reads ka overhead reduce kar sakti hai.', 'try (var reader = new java.io.StringReader("QA")) {\n    int ch;\n    while ((ch = reader.read()) != -1) System.out.println((char) ch);\n}', 'Q\nA', 'read next UTF-16 char value deta hai. -1 sentinel ko char cast karne se pehle check karna chahiye. Resource closes when block ends; enclosing method may declare IOException.', 'read result char mein directly store karoge to -1 end marker lose kar sakte ho.', 'Character source > Reader read > Character or EOF'),
('Writer', 'Writer character output abstraction hai. Underlying encoding bytes produce kar sakti hai. write content append/emit karti hai; flush buffered output forward karti hai; close typically flush+resource release karti hai. StringWriter filesystem ke bina formatter tests useful banati hai. Encoding destination writer setup ka part hai.', 'var writer = new java.io.StringWriter();\nwriter.write("QA");\nwriter.write(" report");\nSystem.out.println(writer.toString());', 'QA report', 'StringWriter memory buffer update karti hai. toString accumulated content return karta hai. External Writer ke close/flush requirements actual resource contract follow karein.', 'flush durable disk commit guarantee nahi. Closing caller-owned shared writer unexpectedly baaki pipeline break kar sakta hai.', 'Characters > Writer destination > Buffered / emitted text'),
('File Handling', 'Path location represent karta hai; Files operations implement karti hai. exists, createDirectories, readString, move aur delete roles different hain. Tests temp files use karein aur cleanup deterministic rakhein. exists then open check race possible hai, so operation ki exception handling still chahiye.', 'var dir = java.nio.file.Files.createTempDirectory("qa-");\nvar file = dir.resolve("result.txt");\njava.nio.file.Files.writeString(file, "PASS");\nSystem.out.println(java.nio.file.Files.exists(file));\njava.nio.file.Files.delete(file);\njava.nio.file.Files.delete(dir);', 'true; temporary file and directory then removed.', 'resolve child location build karta hai. File created before existence observation. Delete ordering file before nonempty directory essential hai. Real tests finally cleanup use karein.', 'Filename user input ho to path traversal constraints required hain. String slash concatenation se platform assumptions avoid karo.', 'Temp directory > Resolved file write > Cleanup owned resources'),
('BufferedReader', 'BufferedReader input ko chunks mein buffer karke character reading efficient banati hai. readLine newline remove karke text return karti hai, EOF par null. Empty line empty string hai, null nahi. Streaming large file memory use reduce kar sakti hai versus read-all. Resource try-with-resources se close karo.', 'try (var reader = new java.io.BufferedReader(new java.io.StringReader("PASS\nFAIL"))) {\n    String line;\n    while ((line = reader.readLine()) != null) System.out.println(line);\n}', 'PASS\nFAIL', 'Buffered reader two lines read karta hai. Each returned value no newline include karti hai. End null loop stop karta hai; empty line would print blank and continue.', 'ready() EOF detector nahi. BufferedReader wrapping same source ke saath competing reads confusing state create kar sakti hain.', 'Text source > Buffer > readLine until null'),
('BufferedWriter', 'BufferedWriter small writes aggregate karke destination IO overhead reduce karti hai. newLine platform line separator emit karti hai. Try-with-resources successful/failing block exit par close initiates; errors handle karo. Append versus overwrite opening option explicitly choose karo for report retention.', 'var path = java.nio.file.Path.of("qa-report.txt");\ntry (var writer = java.nio.file.Files.newBufferedWriter(path, java.nio.charset.StandardCharsets.UTF_8)) {\n    writer.write("PASS");\n    writer.newLine();\n}', 'Creates/replaces qa-report.txt containing PASS and a line separator.', 'write buffer fill karti hai. newLine portable separator add karti hai. close flushes buffered content and releases file. IOException handling/declaring required hai.', 'Buffered data close/flush se pehle visible/durable assume mat karo. Report path per parallel test unique rakho.', 'Small writes > Output buffer > Flush / close destination'),
('NIO Basics', 'NIO Path, Files, buffers/channels aur filesystem APIs provide karti hai. Path syntax-aware location hai, Files high-level helper class hai. NIO ka har operation nonblocking nahi; Files.readString blocking read hai. Large streams close karo, especially Files.lines directory traversal APIs.', 'var root = java.nio.file.Path.of("reports");\nvar child = root.resolve("smoke.txt").normalize();\nSystem.out.println(child.getFileName());', 'smoke.txt', 'resolve relative child combine karta hai. normalize syntactic redundant segments remove karta hai, filesystem symlinks resolve nahi karta. getFileName last path component deta hai.', 'normalize security containment prove nahi karti when symlinks matter. toRealPath existing filesystem resolution karti hai with IO concerns.', 'Path components > Resolve / normalize > Filesystem operation'),
])

add(15, [
('Networking Introduction', 'Networking remote processes ke beech data exchange hai. Protocol application format aur transport expectations define karta hai. HTTP client service response receive karta hai; timeout aur non-2xx status normal failure scenarios hain. Network boundary ko tests mein real local server ya verified stub se exercise kar sakte ho.', 'var client = java.net.http.HttpClient.newHttpClient();\nvar request = java.net.http.HttpRequest.newBuilder(java.net.URI.create("http://localhost:8080/health"))\n    .timeout(java.time.Duration.ofSeconds(2)).GET().build();', 'Builds an HTTP request; no network call occurs until client.send/sendAsync.', 'URI destination identify karti hai. GET request operation hai. Request timeout bounded waiting configure karti hai. send needs body handler and checked exception handling.', 'Request object create karna connectivity prove nahi karta. HTTP 500 transport exception necessarily nahi; status explicitly inspect karo.', 'Client request > Network transport > Server response'),
('Socket Programming', 'Socket TCP byte-stream connection represent karta hai. TCP reliable ordered bytes deta hai, application messages boundaries nahi. Protocol delimiter/length framing define karo. connect timeout aur read timeout separately set ho sakte hain. Client/server dono read-first karenge to blocking hang possible hai.', 'try (var socket = new java.net.Socket()) {\n    socket.connect(new java.net.InetSocketAddress("localhost", 9000), 2000);\n    socket.setSoTimeout(2000);\n    socket.getOutputStream().write("PING\n".getBytes(java.nio.charset.StandardCharsets.UTF_8));\n}', 'Sends PING plus newline if a local TCP server accepts the connection.', 'connect establishes transport. setSoTimeout limits blocking reads, connection establishment nahi. Output bytes newline-delimited protocol suggest karti hain. Local server required; IOException possible.', 'One write equals one read/message assumption wrong. Always specify character encoding for text protocol.', 'Connect TCP > Send framed bytes > Peer reads protocol'),
('ServerSocket', 'ServerSocket listening endpoint hai. accept incoming connection wait karke separate Socket return karta hai. Listener close aur accepted socket close distinct ownership hain. Single accept example one client handle karta hai; concurrent server worker policy separately chahiye. Tests ephemeral port zero choose karke conflicts reduce kar sakte hain.', 'try (var server = new java.net.ServerSocket(0)) {\n    System.out.println(server.getLocalPort() > 0);\n    server.setSoTimeout(2000);\n    // server.accept() waits for a client; handle and close its Socket.\n}', 'true; allocates an available local port then closes the listener.', 'Port zero OS ko free port select karne deta hai. getLocalPort chosen port return karta hai. Timeout accept waiting limit kar sakta hai; accept commented to avoid idle blocking.', 'Hardcoded test port parallel executions conflict kar sakta hai. Listening socket close accepted clients automatically manage nahi karta.', 'Bind listener > accept connection > Handle owned client socket'),
('URL', 'URL resource locator fields identify karta hai: scheme, host, port, path/query. URI identifier parsing ke liye useful hai; conversion valid supported scheme ke saath URL de sakti hai. Parsing locator network fetch nahi karti. User-controlled addresses ke actual requests ke liye allowed destinations validate karo.', 'var uri = java.net.URI.create("https://example.com/payments?id=P1");\nSystem.out.println(uri.getHost());\nSystem.out.println(uri.getPath());\nSystem.out.println(uri.getQuery());', 'example.com\n/payments\nid=P1', 'URI parsed structure parts read karta hai without network. Query raw/decoded distinctions relevant hain; spaces/encoding correctly construct karo. HttpClient request commonly URI use karti hai.', 'String concat URL parameters reserved characters break kar sakte hain. URL constructor APIs target JDK evolution follow karo; URI.toURL often preferable.', 'Locator text > Parsed URI parts > Optional network request'),
])

add(10, [
('Collections Class', 'Collections utility class static algorithms provide karti hai; Collection interface container contract hai. sort, reverse, min aur unmodifiableList different purposes serve karte hain. Utility operation original list mutate karti hai ya new wrapper deti hai, ye API-specific hai. QA data order aur mutability expectations explicitly verify karo.', 'var values = new java.util.ArrayList<>(java.util.List.of(3, 1, 2));\njava.util.Collections.sort(values);\njava.util.Collections.reverse(values);\nSystem.out.println(values);', '[3, 2, 1]', 'sort ascending order mutate karti hai; reverse sorted list ko reverse karti hai. Original values now descending hain. List.of directly immutable/unmodifiable list hoti, so mutable ArrayList copy banayi.', 'Collections aur Collection names similar hain but roles different. Unmodifiable view underlying mutable collection ke changes reflect kar sakti hai.', 'Mutable list > Collections algorithms > Changed order'),
('Collection Interface', 'Collection common element-container operations define karti hai: size, add, remove, contains aur iteration. List, Set aur Queue subinterfaces specific contracts add karti hain. Map Collection subtype nahi. Optional operations implementation par depend karti hain; interface reference hona mutability guarantee nahi deta.', 'java.util.Collection<String> items = new java.util.ArrayList<>();\nitems.add("smoke");\nitems.add("regression");\nSystem.out.println(items.size());\nSystem.out.println(items.contains("smoke"));', '2\ntrue', 'Collection variable common contract expose karti hai. Actual ArrayList supports add aur duplicates. get(index) Collection interface ka method nahi; indexed access requires List contract.', 'Every Collection ordered ya duplicate-free nahi. UnsupportedOperationException optional mutating operations se aa sakti hai.', 'Collection contract > Concrete implementation > Supported operations'),
('List', 'List ordered positional collection hai, duplicates allowed hain. ArrayList random access aur append ke common workloads ke liye useful hai. LinkedList ke performance tradeoffs differ hain; automatically faster inserts kehna location lookup ignore karta hai. QA expected ordered rows aur report output ko List se represent kar sakte ho.', 'java.util.List<String> tests = new java.util.ArrayList<>();\ntests.add("login");\ntests.add("login");\nSystem.out.println(tests.get(1));\nSystem.out.println(tests.size());', 'login\n2', 'Duplicate add allowed hai. get(1) second positional element hai. List index zero-based hai. remove by index aur remove by object overloads Integer list mein particularly careful use karo.', 'List.of unmodifiable hai aur null elements reject karti hai. ArrayList shared concurrent mutations safe nahi.', 'Ordered positions > Duplicate elements allowed > Indexed read'),
('Set', 'Set duplicate elements exclude karti hai according to equality contract. HashSet iteration order unspecified hai; LinkedHashSet insertion order retain karti hai; TreeSet comparison-based sorted uniqueness use karti hai. QA unique payment IDs validate karne mein Set useful hai. Equality/hash consistency element identity define karti hai.', 'java.util.Set<String> ids = new java.util.LinkedHashSet<>();\nSystem.out.println(ids.add("P1"));\nSystem.out.println(ids.add("P1"));\nSystem.out.println(ids);', 'true\nfalse\n[P1]', 'First add set change karti hai, true. Duplicate add state unchanged rakhti hai, false. LinkedHashSet predictable insertion order useful diagnostics deti hai.', 'HashSet iteration order ko assertion expectation mat banao. Mutable hash identity set membership break kar sakti hai.', 'Candidate element > Equality uniqueness check > Add or reject duplicate'),
('Queue', 'Queue pending work ka contract hai. Typical FIFO implementation first-in first-out deti hai; PriorityQueue priority order use karti hai, so all queues FIFO nahi. offer/poll/peek special-value variants hain; add/remove/element exception variants. Empty queue behavior intentionally choose karo. Async processing mein capacity/backpressure crucial hai.', 'java.util.Queue<String> jobs = new java.util.ArrayDeque<>();\njobs.offer("smoke");\njobs.offer("regression");\nSystem.out.println(jobs.poll());\nSystem.out.println(jobs.peek());', 'smoke\nregression', 'offer enqueue karta hai. poll head remove+return karta hai. peek next head read karta hai without removal. Empty poll null return karti hai for this implementation.', 'PriorityQueue iterator sorted traversal guarantee nahi karta. Unbounded producer queue memory grow kar sakti hai.', 'Offer pending jobs > Queue head > Poll next work'),
('Map', 'Map keys ko values associate karti hai. Same key par put existing mapping replace karta hai; duplicate keys simultaneously nahi. HashMap null support aur order rules ConcurrentHashMap se differ hain. get null missing mapping ya null value ho sakti hai, so containsKey relevant hai. QA expected IDs ko actual records se join karne mein useful hai.', 'java.util.Map<String, Integer> status = new java.util.HashMap<>();\nstatus.put("P1", 200);\nstatus.put("P1", 201);\nSystem.out.println(status.get("P1"));\nSystem.out.println(status.size());', '201\n1', 'Second put P1 mapping replace karta hai. Key count one rehta hai. iteration entrySet se key+value pairs milte hain. Map Collection subtype nahi, views collections hain.', 'get==null universally missing prove nahi karta. HashMap shared writes ko synchronization ke bina safe mat assume karo.', 'Key P1 > Mapping lookup > Latest value 201'),
('Iterator', 'Iterator collection traversal state hold karta hai. hasNext availability check karti hai; next element deta hai; optional remove last returned element remove karta hai. Enhanced for generally iterator use karti hai. Direct collection modification during fail-fast iteration error de sakti hai. Concurrent implementations ke traversal semantics separately defined hain.', 'var items = new java.util.ArrayList<>(java.util.List.of("PASS", "SKIP"));\nvar it = items.iterator();\nwhile (it.hasNext()) {\n    if (it.next().equals("SKIP")) it.remove();\n}\nSystem.out.println(items);', '[PASS]', 'Iterator next item select karta hai. Its own remove supported ArrayList iterator se safe deletion karta hai. SKIP remove hota hai and traversal continue karti hai.', 'Fail-fast detection best-effort hai, thread safety mechanism nahi. next bina available item NoSuchElementException de sakta hai.', 'Iterator cursor > next element > Iterator-controlled removal'),
('Comparable', 'Comparable type ka natural ordering define karta hai through compareTo. Negative, zero, positive relative ordering indicate karte hain, necessarily -1/0/1 values nahi. Sorted structures equality-by-comparison use kar sakti hain. Natural order domain stable ho tab define karo; multiple display order requirements Comparator se better handle hote hain.', 'record Score(int value) implements Comparable<Score> {\n    public int compareTo(Score other) { return Integer.compare(value, other.value); }\n}\n// Inside main:\nSystem.out.println(new Score(5).compareTo(new Score(8)) < 0);', 'true', 'Integer.compare safe relative comparison karta hai. value 5 before 8 hai. Comparable implementation class-level default order define karti hai. Sorting list uses this contract without external comparator.', 'a-b subtraction comparator overflow kar sakti hai. TreeSet mein compareTo zero uniqueness affect karti hai, equals alignment consider karo.', 'Type natural order > compareTo pair > Sorted placement'),
('Comparator', 'Comparator external ordering strategy hai. Same Payment list ID, amount ya timestamp se sort kar sakti hai without changing class. comparing aur thenComparing multi-key rules build karte hain. Null handling explicit choose karo. QA stable report sorting ke ties test karo; single-key sort deterministic tie order requirement meet na kare.', 'var names = new java.util.ArrayList<>(java.util.List.of("aa", "b", "cc"));\nnames.sort(java.util.Comparator.comparingInt(String::length).thenComparing(java.util.Comparator.naturalOrder()));\nSystem.out.println(names);', '[b, aa, cc]', 'Length primary key hai. Equal length aa/cc alphabetical secondary key se ordered hain. Comparator data objects ko mutate nahi karti; list sort positions change karta hai.', 'Comparator inconsistent/transitivity-broken ho to sorting failure ya strange ordered-set behavior aa sakta hai.', 'Primary comparison > Tie-break comparison > Ordered result'),
('HashMap Internals', 'HashMap hash se candidate bucket choose karti hai, phir equality se exact key identify karti hai. Collisions multiple keys ko same bucket la sakte hain. Capacity aur load factor resizing influence karte hain. Implementation conditions ke under collision bins treeify ho sakte hain; exact thresholds internal detail hain. Average lookup efficient hai, guarantee every case constant nahi.', 'java.util.Map<String, Integer> values = new java.util.HashMap<>();\nvalues.put("Aa", 1);\nvalues.put("BB", 2);\nSystem.out.println("Aa".hashCode() == "BB".hashCode());\nSystem.out.println(values.get("BB"));', 'true\n2', 'Strings Aa/BB same hash but unequal content have. Map retains both mappings and equality selects BB value. Hash alone key identity prove nahi karta.', 'HashMap iteration order unspecified hai. Key hash-relevant fields mutate karna entry practically unreachable bana sakta hai.', 'Key hash > Candidate bucket > equals selects entry'),
('equals() & hashCode()', 'Logical equality define karte waqt equals reflexive, symmetric, transitive aur consistent honi chahiye. Equal objects same hashCode return karne chahiye; same hash non-equal objects possible hain. HashMap/HashSet both contracts par depend karte hain. Identity fields stable rakho, especially keys in containers.', 'record Id(String value) {}\n// Inside main:\nvar set = new java.util.HashSet<Id>();\nset.add(new Id("P1"));\nset.add(new Id("P1"));\nSystem.out.println(set.size());', '1', 'Record component-based equals/hashCode provide karti hai. Second equal ID duplicate reject hoti hai. If equals override but hash inherited identity-based ho to logically equal elements incorrect buckets mein ja sakte hain.', 'hashCode unique ID nahi. Collection mein inserted key ki equality state change karna dangerous hai.', 'Logical identity > Consistent hash > Correct set/map behavior'),
])

add(11, [
('Lambda Expressions', 'Lambda functional interface ki compact implementation hai. Parameters left aur behavior right side -> se separate hote hain. Target type compiler ko method contract batata hai. Captured local variables final/effectively final honi chahiye. Lambda ka this enclosing instance ko refer karta hai, anonymous object receiver ko nahi.', 'java.util.function.IntUnaryOperator doubled = x -> x * 2;\nSystem.out.println(doubled.applyAsInt(5));', '10', 'IntUnaryOperator one int input/int result contract deta hai. Lambda x*2 implementation hai. Invocation operation execute karti hai; variable declaration alone expression run nahi karti.', 'Captured mutable objects still mutate ho sakte hain; effectively-final reference object immutability guarantee nahi.', 'Target contract > Lambda implementation > Invocation result'),
('Predicate', 'Predicate<T> boolean test express karta hai. filter, validation rules aur reusable conditions mein useful hai. and/or short-circuit combinations aur negate opposite rule build karte hain. Predicate ko side-effect-free rakhna repeated evaluation aur tests easier banata hai. Domain failures need richer explanation ho to boolean alone insufficient ho sakta hai.', 'java.util.function.Predicate<Integer> success = s -> s >= 200 && s < 300;\nSystem.out.println(success.test(201));\nSystem.out.println(success.test(400));', 'true\nfalse', 'test one value evaluate karta hai. 201 accepted range mein hai; 400 outside hai. Boundary 199,200,299,300 test karo. Null Integer input lambda unboxing par NPE dega unless handled.', 'Predicate false ka reason automatically available nahi. Validation messages separate design chahiye.', 'Input value > Boolean rule test > Accepted / rejected'),
('Consumer', 'Consumer<T> input receive karke no result return karta hai. Logging, event notification aur forEach-style actions examples hain. andThen operations sequential compose karta hai. Side effects exactly-once guarantee lambda construct se nahi milti; calling context decide karta hai. QA assertion collector ya diagnostic sink consumer ho sakta hai.', 'java.util.function.Consumer<String> log = s -> System.out.println("Test: " + s);\nlog.accept("smoke");', 'Test: smoke', 'accept operation executes side effect. No mapped value return hoti. If first composed Consumer throws, next normally execute nahi hoti. Output order depends calling traversal.', 'Consumer ko Stream.map mein value transform ke liye use mat karo. Shared mutable sink parallel stream mein races la sakta hai.', 'Input test name > accept side effect > Log output'),
('Supplier', 'Supplier<T> no input lekar value produce karta hai. Deferred construction, fallback aur fresh test-data factory mein useful hai. Supplier evaluation caller ke get call par hoti hai; caching/memoization automatically nahi. Fresh object chahiye ya same object, implementation contract decide karta hai.', 'java.util.function.Supplier<java.util.List<String>> factory = java.util.ArrayList::new;\nvar a = factory.get();\nvar b = factory.get();\nSystem.out.println(a == b);', 'false', 'Constructor reference each get par new list banati hai. Independent test data cross-case mutation reduce karta hai. Constant supplier however same object return kar sakti hai.', 'Supplier always fresh ya lazy-once hai assume mat karo. Expensive get may repeat every call.', 'Deferred factory > get invocation > New value'),
('Method References', 'Method reference compatible existing method ko functional interface implementation ke roop mein refer karti hai. Static Type::method, bound object::method, unbound Type::instanceMethod aur Type::new common forms hain. Signature target function se match honi chahiye. Ye method immediately execute nahi karti; invocation later hoti hai.', 'java.util.function.Function<String, Integer> parse = Integer::parseInt;\nSystem.out.println(parse.apply("42"));', '42', 'Integer::parseInt one String -> Integer-compatible result provide karta hai. apply input conversion execute karti hai. x -> Integer.parseInt(x) equivalent simple lambda hai.', 'Overloaded method reference ambiguous ho sakti hai without clear target type. Null bound receiver reference create karte waqt fail ho sakta hai.', 'Existing method > Functional adapter > apply executes'),
('Streams', 'Stream data source par processing pipeline hai, storage container nahi. Intermediate operations lazy hain; terminal operation work trigger karti hai. Stream generally single-use hai. filter/map declarative transforms express karte hain, but side effects aur parallel behavior consciously reason karo. Original list mutate karna necessary nahi.', 'var source = java.util.List.of(1, 2, 3, 4);\nvar result = source.stream().filter(n -> n % 2 == 0).map(n -> n * 10).toList();\nSystem.out.println(result);\nSystem.out.println(source);', '[20, 40]\n[1, 2, 3, 4]', 'filter keeps 2/4; map transforms to 20/40; toList terminal collection trigger karti hai. Source values unchanged. Java 17+ Stream.toList result unmodifiable hai.', 'Stream reuse after terminal operation illegal hai. parallel automatically faster nahi aur mutable shared state risky hai.', 'Source > Lazy filter + map > Terminal result'),
('map/filter/reduce', 'filter elements select karta hai; map each element transform karta hai; reduce multiple values combine karta hai. Identity neutral value honi chahiye aur accumulator associativity especially parallel evaluation ke liye important hai. Payment amounts pipeline mein invalid entries filter, tax transform aur total reduce kar sakte ho.', 'int total = java.util.List.of(-1, 2, 3).stream()\n    .filter(n -> n > 0)\n    .map(n -> n * 10)\n    .reduce(0, Integer::sum);\nSystem.out.println(total);', '50', 'Filter -1 discard karti hai. Map 2/3 to 20/30 banata hai. Reduce identity zero se sum 50 banta hai. Empty input identity zero return karegi.', 'Subtraction parallel reduce ke liye associative nahi. map ka side effect final result calculation ko fragile bana sakta hai.', 'Select positives > Transform x10 > Reduce sum 50'),
('Collectors', 'Collectors terminal reduction strategies deti hain: groupingBy, joining, counting aur toMap. Grouping category-wise test report useful hai. toMap duplicate keys policy require kar sakti hai; merge rule intentionally define karo. Returned collection type/mutability ko collector contract se samjho, incidental implementation se nahi.', 'var grouped = java.util.List.of("PASS", "FAIL", "PASS").stream()\n    .collect(java.util.stream.Collectors.groupingBy(s -> s, java.util.stream.Collectors.counting()));\nSystem.out.println(grouped.get("PASS"));', '2', 'Classifier same status strings group karta hai. Downstream counting har group ka long count produce karti hai. Map print ordering unspecified ho sakti hai, so specific key assert karo.', 'toMap with duplicate key and no merge function throws. Collectors.toList concrete list implementation promise nahi karti.', 'Stream statuses > Group by status > Count each group'),
('Optional', 'Optional absence/presence ka explicit return wrapper hai. map/filter/orElseGet result pipeline simplify karti hain. Optional null ko wrapped present value nahi rakhti; ofNullable null par empty deti hai. Every field/parameter Optional banana zaroori nahi. Missing value business error hai ya valid absence, pehle decide karo.', 'String input = null;\nString name = java.util.Optional.ofNullable(input).map(String::strip).orElseGet(() -> "Unknown");\nSystem.out.println(name);', 'Unknown', 'ofNullable empty banati hai. map absent value par execute nahi hoti. orElseGet supplier only absence mein evaluate hota hai. orElse supplied expression eagerly evaluate ho sakti hai.', 'Optional.get bina presence check failure deta hai. Optional itself null return karna contract defeat karta hai.', 'Nullable input > Present/empty branch > Deferred fallback'),
])

add(12, [
('Date/Time Introduction', 'java.time immutable date/time types roles separate karti hain. LocalDate calendar date, LocalTime wall-clock time, Instant global timeline point aur ZonedDateTime zone-aware representation hai. Oslo daylight-saving transitions ko UTC assumptions se mix mat karo. QA deterministic time ke liye Clock inject kar sakta hai instead of direct now.', 'var fixed = java.time.Clock.fixed(java.time.Instant.parse("2026-09-30T10:00:00Z"), java.time.ZoneId.of("Europe/Oslo"));\nSystem.out.println(java.time.LocalDate.now(fixed));', '2026-09-30', 'Clock fixed instant aur zone supply karta hai. LocalDate date calculate karti hai without live wall clock dependence. Same clock repeatable assertions deta hai.', 'LocalDateTime alone absolute moment identify nahi karti. System default zone test machine ke saath change ho sakta hai.', 'Instant + Zone > Fixed Clock > Deterministic local date'),
('LocalDate', 'LocalDate timezone-free calendar date hai, birthday ya due date ke liye useful. plusDays/plusMonths new values return karti hain, original mutate nahi hoti. Leap years aur month-end adjustment relevant boundaries hain. Zoned conversion tab karo jab date ko actual day-start instant se connect karna required ho.', 'var date = java.time.LocalDate.of(2026, 1, 31);\nSystem.out.println(date.plusMonths(1));\nSystem.out.println(date);', '2026-02-28\n2026-01-31', 'February mein 31st nahi, so plusMonths valid month-end adjust karti hai. Original remains Jan31. Date subtraction calendar arithmetic hai, necessarily exact elapsed hours nahi.', 'Date ko 24-hour duration ka synonym mat samjho, DST days vary kar sakte hain.', 'Calendar date > plusMonths adjustment > New valid date'),
('LocalTime', 'LocalTime date aur timezone ke bina wall-clock time hai. Office opening 09:00 jaise recurring times represent kar sakti hai. Day rollover arithmetic wrap karti hai; actual next calendar date is type mein store nahi hoti. Scheduling full instant ko date aur zone bhi chahiye.', 'var time = java.time.LocalTime.of(23, 30);\nSystem.out.println(time.plusHours(2));', '01:30', 'Addition midnight cross karti hai aur 24-hour clock wrap hoti hai. Result next-day date include nahi karta. nanosecond precision possible hai but source clock resolution different ho sakti hai.', 'LocalTime compare se overnight interval automatically correct nahi hota; date/day boundary account karo.', 'Wall-clock 23:30 > Add 2 hours > 01:30 without date'),
('LocalDateTime', 'LocalDateTime local date aur local clock combine karti hai, timezone/offset ke bina. It can represent meeting local fields, but DST overlap mein same local time two instants map kar sakti hai; gap mein valid instant na ho. Persisting distributed event timestamp ke liye Instant/offset-aware representation often better hai.', 'var local = java.time.LocalDateTime.of(2026, 9, 30, 12, 0);\nvar zoned = local.atZone(java.time.ZoneId.of("Europe/Oslo"));\nSystem.out.println(zoned.toInstant());', '2026-09-30T10:00:00Z', 'Zone rules September Oslo offset apply karti hain. atZone local fields resolve karta hai; toInstant global point deta hai. DST boundaries separately test karo.', 'Server default timezone silently attach karna global events shift kar sakta hai. Offset alone future regional DST rules carry nahi karta.', 'Local date/time > Apply Oslo zone rules > Global instant'),
('Duration', 'Duration time-based amount seconds/nanos represent karti hai. API response elapsed time, timeout aur exact delay ke liye useful hai. Instant pair ke beech actual elapsed duration nikaal sakte ho. Long-running performance measurements ke liye monotonic System.nanoTime clock suitable hai; wall clock jump kar sakti hai.', 'var start = java.time.Instant.parse("2026-09-30T10:00:00Z");\nvar end = start.plusSeconds(90);\nSystem.out.println(java.time.Duration.between(start, end).toSeconds());', '90', 'between start/end difference calculate karti hai. toSeconds whole second amount deta hai. Duration.ofDays(1) exact 24 hours hai, calendar next-day same-local-time always nahi.', 'Period days aur Duration hours DST par different results de sakte hain.', 'Start instant > End instant > Elapsed 90 seconds'),
('Period', 'Period calendar-based years/months/days amount hai. Age ya monthly schedule calendar calculation mein useful hai. Duration exact timeline time represent karti hai; Period human calendar units. Months unequal length hain, so one month fixed seconds nahi. Period components ko total months/days samajhne se pehle API contract dekho.', 'var birthday = java.time.LocalDate.of(2025, 9, 13);\nvar today = java.time.LocalDate.of(2026, 9, 30);\nSystem.out.println(java.time.Period.between(birthday, today));', 'P1Y17D', 'Calendar difference one year plus seventeen days hai. getDays remainder days deta hai, total elapsed days nahi. Total date-day difference chahiye to ChronoUnit.DAYS.between use karo.', 'Period.getDays total days nahi. Month-end behavior aur leap birthdays meaningful test cases hain.', 'Calendar start > Year/month/day difference > Period components'),
('DateTimeFormatter', 'Formatter text aur date/time values ke conversion rules define karta hai. Pattern case significant hai: MM month, mm minute; yyyy year-of-era, uuuu proleptic year. ISO format interoperability mein useful hai. Strict parsing invalid dates reject kare; locale month-name parsing influence karta hai.', 'var fmt = java.time.format.DateTimeFormatter.ofPattern("dd.MM.uuuu").withResolverStyle(java.time.format.ResolverStyle.STRICT);\nvar date = java.time.LocalDate.parse("30.09.2026", fmt);\nSystem.out.println(date);', '2026-09-30', 'Pattern day-month-year input interpret karta hai. Strict resolution calendar validity check karti hai. Same formatter format(date) se Norwegian-style display de sakti hai.', 'YYYY week-based year hai aur year-end surprising output de sakta hai. Invalid input tests include 31.02.2026.', 'Text pattern > Strict parser > Valid LocalDate'),
])

add(6, [
('Exception Basics', 'Exception normal execution ko interrupt karke failure information propagate karti hai. Checked exceptions ko catch ya declare karna hota hai; RuntimeException subclasses unchecked hain. Error usually serious runtime/system condition represent karta hai. QA mein expected failure contract verify karo: wrong input kya reject hoti hai aur state preserve hoti hai?', 'static int parse(String text) { return Integer.parseInt(text); }\n// Inside main:\nSystem.out.println(parse("42"));\n// parse("abc") throws NumberFormatException', '42; invalid text fails with NumberFormatException.', 'Numeric characters conversion successful hai. Invalid token method se exception propagate karta hai; result value return nahi hoti. Caller recovery ya reporting decide karta hai.', 'Exception ko swallow karke zero return karna failure ko valid data jaisa bana sakta hai. Catch only jab meaningful handling possible ho.', 'Operation > Failure object > Caller handling'),
('try/catch', 'try risky operation ka boundary hai; catch matching exception type handle karti hai. First compatible catch selected hoti hai, so specific types broad types se pehle honi chahiye. Recovery meaningful honi chahiye: fallback, reject input ya propagate with context. Successful path aur caught path separately test karo.', 'try {\n    int count = Integer.parseInt("abc");\n    System.out.println(count);\n} catch (NumberFormatException ex) {\n    System.out.println("Invalid count");\n}', 'Invalid count', 'parseInt failure ke baad println(count) skip hota hai. Matching catch execute hoti hai. Block ke baad normal continuation possible hai if handler itself throws nahi karta.', 'catch(Exception) har failure ko same label dene se programming bugs hide ho sakte hain. Exception message stable assertion contract nahi always.', 'Try parse > NumberFormatException > Specific catch'),
('finally', 'finally cleanup code normally success aur failure dono exits par execute karta hai. Resource ownership clear ho to try-with-resources AutoCloseable resources close karne ka preferred approach hai. finally return value change ya exception mask kar sakta hai if usmein return/throw likho. JVM termination/crash mein finally guarantee mat assume karo.', 'try {\n    System.out.println("work");\n    throw new IllegalStateException("failed");\n} catch (IllegalStateException ex) {\n    System.out.println("handled");\n} finally {\n    System.out.println("cleanup");\n}', 'work\nhandled\ncleanup', 'Failure catch tak jaati hai; finally handler ke baad execute hota hai. Successful case mein bhi cleanup chalega. Resources ke close order aur suppressed exceptions try-with-resources handle karti hai.', 'finally ke return se earlier return/exception override ho sakti hai. final modifier aur finally block unrelated concepts hain.', 'Work / failure > Handler > Cleanup'),
('throw vs throws', 'throw actual exception raise karta hai. throws method signature mein possible checked failures declare karta hai, exception execute nahi karta. Unchecked exceptions declare karna optional hai. API contract mein declared failure caller ko handling obligation batati hai. Business validation ke runtime exceptions ko explicit response mapping chahiye ho sakti hai.', 'static void validate(int amount) {\n    if (amount <= 0) throw new IllegalArgumentException("positive amount required");\n}\nstatic String load(java.nio.file.Path p) throws java.io.IOException {\n    return java.nio.file.Files.readString(p);\n}', 'validate(0) fails; load may propagate IOException.', 'throw invalid input par control transfer karta hai. load ka throws IOException checked failure caller ko expose karta hai. Successful file read String return karti hai.', 'throws likhne se runtime automatically catch nahi karta. throw ke baad unreachable code write karna compilation problem hai.', 'Method contract throws > Operation detects failure > throw transfers control'),
('Custom Exceptions', 'Custom exception domain-specific failure communicate karti hai, jaise insufficient funds. Checked vs unchecked choice recovery contract se decide karo. Meaningful constructor message aur cause preserve kar sakta hai. Har tiny validation ke liye new hierarchy unnecessary hai; consumers ko distinguish karna useful ho tab custom type banao.', 'class InsufficientFunds extends RuntimeException {\n    InsufficientFunds(int available) { super("Available: " + available); }\n}\nstatic void debit(int balance, int amount) {\n    if (amount > balance) throw new InsufficientFunds(balance);\n}', 'debit(50, 80) throws InsufficientFunds with Available: 50.', 'Failure type business reason identify karti hai. Caller amount-balance relation validate kar sakta hai; service state mutate karne se pehle reject kare. HTTP layer can map this to chosen client-error contract.', 'Custom exception mein secrets ya complete account details expose mat karo. Generic success return se rejected payment hide mat karo.', 'Debit request > Balance rule > Domain exception'),
('Chained Exceptions', 'Chaining low-level cause ko higher-level context ke saath preserve karti hai. Repository IOException ko report-generation failure mein wrap kar sakti hai while original cause retained rahe. Logs se actual root cause trace ho sakta hai. Human-friendly error message aur internal diagnostic cause separate purposes serve karte hain.', 'try {\n    Integer.parseInt("bad");\n} catch (NumberFormatException cause) {\n    throw new IllegalArgumentException("Invalid retry configuration", cause);\n}', 'Top-level IllegalArgumentException; cause is NumberFormatException.', 'Wrapper operation context batata hai. getCause original parse failure deta hai. Stack trace nested origin retain karti hai, so configuration location aur numeric conversion dono inspect ho sakte hain.', 'new Exception(cause.getMessage()) original stack/cause chain lose karti hai. Same exception ko har layer log karna duplicate noisy logs laata hai.', 'Low-level failure > Context wrapper > Preserved cause chain'),
('NullPointerException', 'null absence of object reference hai. Null receiver par instance method/field access NPE deti hai. Nullable wrapper unboxing bhi NPE de sakti hai. Fix sirf catch NPE nahi: decide karo input optional hai ya required; required values boundary par reject karo. Optional return APIs absence ko explicit bana sakti hain.', 'String name = null;\nSystem.out.println(java.util.Objects.equals(name, "Harsh"));\nString safe = name == null ? "Unknown" : name;\nSystem.out.println(safe);', 'false\nUnknown', 'Objects.equals nullable comparison handle karta hai. Conditional fallback only if requirement allows missing name. Required input mein Objects.requireNonNull early failure better ho sakta hai. name.length() yahan NPE dega.', 'Null data aur empty data different cases hain. Broad catch NPE genuine programming bug ko hide kar sakta hai.', 'Nullable reference > Validate or fallback > Safe operation'),
('Exceptions with Method Overriding', 'Override parent checked exception contract ko broaden nahi kar sakta. Same exception, subtype ya no checked exception allowed hai. Reason: parent reference use karne wale caller ne parent declared failures ke hisaab se handling likhi hai. Unchecked exceptions par checked declaration restriction same tarah apply nahi hoti.', 'class Parent {\n    void read() throws java.io.IOException {}\n}\nclass Child extends Parent {\n    @Override void read() throws java.io.FileNotFoundException {}\n}', 'Compiles: FileNotFoundException is an IOException subtype.', 'Parent callers IOException handle karte hain, so narrower FileNotFoundException covered hai. Child declaration throws Exception instead kare to broader checked failure compiler reject karega.', 'Method signature match alone override legality prove nahi karta. Access visibility aur return covariance bhi rules follow karein.', 'Parent failure contract > Narrower child failure > Caller compatibility'),
])

add(7, [
('Regex Introduction', 'Regex text patterns define karti hai, jaise payment ID P followed by digits. Pattern compiled expression hai; Matcher input-specific search state hai. Full validation aur substring search alag hain. Regex useful formatting checks karti hai, but account existence/business validity prove nahi karti. Java string escaping aur regex escaping two levels hain.', 'java.util.regex.Pattern pattern = java.util.regex.Pattern.compile("P[0-9]{3}");\nSystem.out.println(pattern.matcher("P123").matches());\nSystem.out.println(pattern.matcher("XP123").matches());', 'true\nfalse', 'P exact letter aur [0-9]{3} exactly three digits require karta hai. matches entire input consume karta hai. Prefix X extra hai, so second validation false hai.', 'Untrusted complex patterns catastrophic backtracking create kar sakte hain. Pattern format check ko business validation ka replacement mat banao.', 'Regex expression > Compiled Pattern > Match input'),
('Matcher', 'Matcher ek pattern ko specific text par apply karta hai. matches whole input check karta hai, find next matching substring search karta hai, group last successful match ka text deta hai. Repeated find search position advance karti hai. Capturing groups structured pieces extract kar sakti hain, jaise order number.', 'var m = java.util.regex.Pattern.compile("P([0-9]+)").matcher("Paid P12 and P34");\nwhile (m.find()) {\n    System.out.println(m.group(1));\n}', '12\n34', 'Each find next P-plus-digits locate karti hai. Group zero full P12 text hai; group one only digit capture hai. Search state iterator jaisi progress karti hai.', 'Successful match se pehle group call IllegalStateException de sakta hai. Same mutable Matcher multiple threads mein share mat karo.', 'Input text > find advances > group extracts capture'),
('Character Classes', 'Character class one character from set match karti hai. [A-Z] uppercase range, [0-9] digit range, [^0-9] non-digit hai. Square brackets ke andar special symbols ke rules normal expression se differ karte hain. Unicode names aur locale inputs ke liye ASCII-only assumption consciously choose karo.', 'String pattern = "[A-Z][0-9]";\nSystem.out.println("A5".matches(pattern));\nSystem.out.println("AA5".matches(pattern));', 'true\nfalse', 'First class exactly one uppercase letter consume karti hai; second one digit. Whole input match required hai, so extra A failure deta hai. Character class alternatives hain, sequence of whole strings nahi.', 'Hyphen class mein range define kar sakta hai. Accented letters [A-Z] mein necessarily match nahi hote.', 'One letter set > One digit set > Two-character match'),
('Quantifiers', 'Quantifier preceding token ki repetition specify karta hai: * zero or more, + one or more, ? zero or one, {m,n} bounded repetitions. Greedy quantifier as much as possible match karti hai while allowing rest; reluctant form minimum se start karti hai. Validation mein bounds useful hain to unreasonable lengths reject karo.', 'String codePattern = "[0-9]{4,6}";\nSystem.out.println("1234".matches(codePattern));\nSystem.out.println("123".matches(codePattern));', 'true\nfalse', 'Digit token four through six times allowed hai. Three digits lower boundary fail karti hain. Test length 3,4,6,7 aur non-digit input cover karo.', '.* bahut permissive hai aur expensive patterns ka part ho sakta hai. Quantifier nearest preceding token/group par apply hoti hai.', 'Digit token > Repeat 4 to 6 > Boundary validation'),
])

add(8, [
('Memory Management', 'JVM object memory allocation aur reclamation manage karti hai. Application ko manual free nahi call karna, par resource ownership aur live references still manage karne hain. Garbage collection unreachable objects ki memory reclaim kar sakti hai; open database/file handles separately close karne chahiye. Memory use allocation rate aur retained live data dono se affected hota hai.', 'byte[] data = new byte[1024];\nSystem.out.println(data.length);\ndata = null;\n// No longer reachable through this variable', '1024; reclamation timing is not deterministic.', 'Array allocate hoti hai. null assignment one reference remove karta hai; agar other references nahi to object potentially collectible hai. Is exact moment GC run hui ya memory returned hui, snippet prove nahi karta.', 'System.gc request guarantee nahi. Auto memory management ka matlab automatic socket/file cleanup par depend karna nahi.', 'Allocate object > Reachable lifetime > Unreachable: GC eligible'),
('Objects in Memory', 'Objects ko references se access karte hain. Multiple variables same object reference kar sakti hain. References ki conceptual graph se aliasing aur retention explain hota hai; exact physical addresses JVM expose nahi karti. Runtime optimization allocations eliminate ya move kar sakti hai, so simplified diagrams conceptual hain.', 'int[] a = {1, 2};\nint[] b = a;\nb[0] = 9;\nSystem.out.println(a[0]);\nSystem.out.println(a == b);', '9\ntrue', 'a aur b same array refer karte hain. b mutation underlying object change karti hai. Equality true identity confirm karti hai. b = new int[]{7} karne se b rebind hoti hai, a old array refer karegi.', 'Reference variable aur object contents ko same cheez mat samjho. Debugger ID physical stable memory address nahi necessarily.', 'Reference a > Shared array object > Reference b'),
('JVM Memory Areas', 'JVM runtime mein thread-specific stacks aur shared heap important areas hain. Stack frames method execution state represent karte hain; heap conceptual object storage hai. Class metadata HotSpot mein metaspace use karti hai; JIT compiled code code cache use karta hai. These areas ke failures aur tuning alag hain.', 'class MemoryDemo {\n    static int shared = 1;\n    int instance = 2;\n    void work() { int local = 3; System.out.println(local); }\n}', 'new MemoryDemo().work() prints 3.', 'local current invocation ka frame state hai. instance receiver object ki field hai. shared class-level state hai. Diagram logical ownership samjhata hai, exact optimized storage layout nahi.', 'Metaspace ko heap ka ordinary object bucket mat bolo. StackOverflowError aur heap OutOfMemoryError different diagnoses demand karte hain.', 'Thread stack frames > Shared heap objects > Class metadata area'),
('Stack vs Heap', 'Stack each thread ki method-call frames track karta hai. Heap live object graph ka shared conceptual area hai. Local reference frame mein ho sakti hai aur uska object heap concept mein; object field mein another reference bhi ho sakti hai. Deep recursion frames exhaust kar sakti hai; large retained object graph heap exhaust kar sakta hai.', 'static int sum(int n) {\n    if (n == 0) return 0;\n    return n + sum(n - 1);\n}\n// Inside main:\nSystem.out.println(sum(3));', '6', 'Calls sum(3),sum(2),sum(1),sum(0) nested frames banati hain. Base case zero return karta hai; results unwind 1,3,6. Very large n stack overflow risk hai; iterative approach avoids growing recursive frames.', 'Local variable always stack and object always physically heap oversimplifies JVM optimizations. Conceptual ownership diagram ko implementation guarantee mat samjho.', 'sum(3) frame > Nested calls > Return unwinds frames'),
('Garbage Collection', 'GC reachable references se liveness determine karti hai, reference count alone se nahi. Cyclic objects bhi collectible ho sakte hain if roots se unreachable hain. Roots include active execution references aur reachable static structures. Eligibility memory immediately reclaimed hone ki guarantee nahi. Large long-lived test caches retention grow kar sakti hain.', 'Object a = new Object();\nObject b = a;\na = null;\nSystem.out.println(b != null);\nb = null; // no reference from a or b remains', 'true; GC timing cannot be inferred.', 'a null karne par b still object retain karta hai. b null ke baad these two references gone hain. Other references present ho to object still live hai. GC scheduling nondeterministic hai.', 'GC request ko timing assertion mat banao. Weak reference clear hona bhi precise application cleanup scheduler nahi.', 'Root reference b > Object remains reachable > Last link removed'),
('Garbage Collectors', 'Collectors different goals balance karte hain: throughput, pause time, memory overhead. Serial, Parallel, G1 aur ZGC availability/defaults JDK aur distribution par depend karte hain. Selection measured workload se karo. QA performance tests realistic heap, allocation rate aur concurrent users ke saath run honi chahiye; single average latency enough nahi.', 'java -Xlog:gc -jar application.jar\n# Example explicit choice, if supported:\njava -XX:+UseG1GC -Xlog:gc -jar application.jar', 'GC logs depend on workload, JDK and collector.', 'First command collector activity log karti hai. Second explicit supported G1 request karti hai. Compare pause distribution, CPU and heap behavior against baseline. Flags runtime-specific hain, source code nahi.', 'Collector change memory leak ka root cause fix nahi karti. Availability aur defaults ko target JDK docs mein verify karo.', 'Workload allocations > Collector policy > Pause / throughput tradeoff'),
('Memory Leaks', 'Managed Java mein leak often unused-but-reachable objects ka retention hai. Static cache, listeners, ThreadLocal aur unbounded queue old data alive rakh sakte hain. GC inko delete nahi karti because graph se reachable hain. Heap dump dominators aur retention paths diagnosis mein useful hain; rising heap alone temporary load bhi ho sakta hai.', 'class Cache {\n    static final java.util.List<byte[]> retained = new java.util.ArrayList<>();\n    static void add() { retained.add(new byte[1024]); }\n    static void clear() { retained.clear(); }\n}', 'Each add retains another 1 KB array, excluding object/list overhead.', 'Static list root-reachable container hai. Each array uske elements se linked rahti hai. clear references remove karta hai; now arrays collectible ho sakti hain if no other owners.', 'Only larger -Xmx increase karna unbounded growth solve nahi karta. Fix cache bounds, eviction aur lifecycle ownership.', 'Static cache root > Growing retained arrays > Unused but still reachable'),
])

add(9, [
('Generic Classes', 'Generics reusable type-safe APIs banati hain. Box<T> same implementation ko String ya Integer ke saath use kar sakta hai without unsafe caller casts. Type parameter compile-time check deta hai; primitive type argument allowed nahi, wrapper use karo. Parameterized types generally invariant hain: Box<Integer> Box<Number> ka subtype nahi.', 'class Box<T> {\n    private final T value;\n    Box(T value) { this.value = value; }\n    T get() { return value; }\n}\n// Inside main:\nBox<String> box = new Box<>("PASS");\nSystem.out.println(box.get());', 'PASS', 'String type argument constructor/get contract specialize karta hai. Diamond inference compiler type choose karti hai. box.get returns String at use site. Box<Integer> independent specialization hai.', 'Raw Box use karna type checking weaken karta hai. new T() cannot directly instantiate unknown type parameter.', 'Type parameter T > Box<String> contract > Typed return'),
('Wildcards', 'Wildcard unknown compatible type represent karti hai. ? extends Number numeric producer se Number read karne deta hai, but arbitrary Number add safe nahi. ? super Integer Integer consumer mein Integer add karne deta hai, read type generally Object hota hai. PECS producer-extends, consumer-super useful guideline hai, absolute design law nahi.', 'static double sum(java.util.List<? extends Number> values) {\n    double total = 0;\n    for (Number n : values) total += n.doubleValue();\n    return total;\n}\n// Inside main:\nSystem.out.println(sum(java.util.List.of(1, 2)));', '3.0', 'List<Integer> acceptable hai because wildcard some Number subtype represent karti hai. Each item Number ke API se read hota hai. values.add(3.5) unsafe hota if actual list Integer ki ho.', 'List<Object> arbitrary List<String> accept nahi karti. extends wildcard mostly reading hai; it does not mean list itself immutable hai.', 'Unknown Number subtype > Read as Number > Numeric sum'),
('Bounded Types', 'Bounded type parameter allowed types constrain karta hai and operations expose karta hai. T extends Number se T value number APIs support karti hai. Multiple bounds mein class bound first honi chahiye. Comparison algorithms mein Comparable bound common hai. Bound compile-time contract hai, runtime input validation ka substitute nahi.', 'static <T extends Number> double doubled(T value) {\n    return value.doubleValue() * 2;\n}\n// Inside main:\nSystem.out.println(doubled(4));', '8.0', 'Integer Number subtype hai, so generic method accept karti hai. Bound doubleValue access legal banata hai. String input compile-time reject hogi. Null still possible hai and dereference failure de sakta hai.', 'extends keyword generic bounds mein interfaces ke liye bhi use hota hai. Bound all semantic values validate nahi karti.', 'T constrained to Number > Number API available > Typed algorithm'),
('Type Erasure', 'Most generic type checks compile time par hoti hain; compiler type parameters ko bounds/Object representations mein erase aur required casts insert karta hai. Runtime ordinary List<String> vs List<Integer> element parameters directly reified nahi hain. Generic signature metadata reflection mein available ho sakti hai, so all generic information disappears kehna oversimplification hai.', 'java.util.List<String> names = new java.util.ArrayList<>();\njava.util.List<Integer> ids = new java.util.ArrayList<>();\nSystem.out.println(names.getClass() == ids.getClass());', 'true', 'Dono runtime ArrayList class use karti hain. Compile-time names mein String aur ids mein Integer add constraints different hain. instanceof List<String> legal ordinary runtime type test nahi; List<?> possible hai.', 'List<String> aur List<Integer> only parameter difference wale overloads same erased signature clash karte hain. Raw types runtime ClassCastException enable kar sakti hain.', 'Generic source checks > Erased runtime class > Inserted casts'),
])

add(0, [
('Java Introduction & Hello World', 'Java program ka source human-readable .java file hota hai. Compiler usko bytecode mein convert karta hai; JVM bytecode execute karti hai. Isi separation se compatible JVM wale systems par same compiled application chal sakti hai. Console program ka traditional entry point main hai; Spring Boot bhi ek main method se application start karta hai.', 'public class Hello {\n    public static void main(String[] args) {\n        System.out.println("Hello, Harsh!");\n    }\n}', 'Hello, Harsh!', 'Hello class program ko naam deti hai. public se launcher main access kar sakta hai; static se object banaye bina invoke hota hai; void batata hai return value nahi. println ek line print karta hai. Save Hello.java, run javac Hello.java, phir java Hello.', 'Public class ka naam aur filename match rakho. Java Hello.class command galat hai; launcher ko class name chahiye, filename nahi.', 'Hello.java source > javac: compile > Hello.class bytecode > JVM: execute'),
('JDK vs JRE vs JVM', 'JVM execution engine hai; JRE runtime environment ka concept hai jisme JVM aur runtime libraries hoti hain. JDK development kit hai jisme compiler, runtime aur diagnostic tools milte hain. Developer aur QA automation engineer ko JDK chahiye, kyunki tests compile bhi karne hain. Modern distributions standalone JRE package har baar provide nahi karti; runtime images bhi ban sakte hain.', 'java -version\njavac -version\njavac Hello.java\njava Hello', 'Version numbers depend on your installed JDK; Hello then prints its message.', 'java runtime launcher ka version dikhata hai. javac compiler verify karta hai. Compiler nahi mil raha par java chal raha hai to runtime available ho sakta hai, development tools ya PATH missing ho sakta hai. Dono commands expected installation se resolve honi chahiye.', 'Newer bytecode ko older JVM par chalane se UnsupportedClassVersionError aa sakta hai. Build target aur runtime version align karo.', 'JDK tools > javac bytecode > Runtime libraries + JVM > Program output'),
('Input & Output', 'Input se program ko external value milti hai; output se result user tak jaata hai. Scanner console text ko tokens mein parse karta hai. nextInt numeric token leta hai, nextLine poori remaining line leta hai. Input valid hai ya nahi, ye assume karne ke bajay check karo. Automation mein input file, environment ya API se bhi aa sakta hai.', 'import java.util.Scanner;\nclass InputDemo {\n    public static void main(String[] args) {\n        Scanner input = new Scanner(System.in);\n        System.out.print("Age: ");\n        int age = input.nextInt();\n        input.nextLine();\n        System.out.print("Name: ");\n        String name = input.nextLine();\n        System.out.println(name + " is " + age);\n    }\n}', 'For input 35 then Harsh: Harsh is 35', 'Scanner System.in read karta hai. nextInt ke baad nextLine pending newline consume karti hai; next nextLine actual name read karti hai. print cursor same line par rakhta hai; println line break add karta hai.', 'nextInt ke turant baad name ke liye nextLine use karoge to empty text mil sakta hai. Shared System.in ko utility method ke andar close mat karo.', 'Console characters > Scanner parsing > Typed values > println result'),
('Identifiers', 'Identifiers developer-chosen names hain: class, variable, method aur package ke. Compiler names ko case-sensitive treat karta hai, isliye status aur Status alag hain. Meaningful names test failure diagnose karne mein help karte hain. Java identifiers letter, underscore ya dollar se start ho sakte hain; later digits aa sakte hain. Unicode allowed hai, par team readability ke liye consistent conventions use karo.', 'int expectedStatus = 200;\nint actualStatus = 201;\nboolean statusMatches = expectedStatus == actualStatus;\nSystem.out.println(statusMatches);', 'false', 'expectedStatus requirement ko naam deta hai; actualStatus observation ko. Dono int hain par roles alag hain. statusMatches boolean expression store karta hai. camelCase variables/methods aur PascalCase classes ka common convention hai.', '2status aur class variable names valid nahi. Keyword ko identifier banana compilation failure hai; similar-looking names accidental bugs la sakte hain.', 'Name declaration > Compiler symbol lookup > Value use'),
('Keywords', 'Keywords language grammar ke reserved words hain. class structure declare karta hai, if decision leta hai, return method se value deta hai. Ye words variable names nahi ban sakte. true, false aur null literals hain, ordinary identifiers nahi. Kuch newer words contextual restrictions ke saath use hote hain; sirf keyword count yaad karna Java samajhna nahi hai.', 'class StatusCheck {\n    static boolean accepted(int status) {\n        if (status == 200) {\n            return true;\n        }\n        return false;\n    }\n}', 'accepted(200) returns true; accepted(500) returns false.', 'class type define karta hai. static method class se belong karti hai. boolean return type hai. if branch condition evaluate karti hai. return caller ko result deta hai aur method execution end karta hai.', 'String ek class ka naam hai, keyword nahi. final, finally aur finalize same cheez nahi hain; unka context alag hai.', 'class grammar > if branch > return result'),
('Variables', 'Variable ko sirf box kehna starting analogy hai: actual rule type, name, scope aur lifetime ka hai. Local variable method call tak relevant hoti hai; instance field har object ki state hoti hai; static field class ke objects mein shared hoti hai. Reference variable object khud nahi, object tak pahunchne ka reference rakhti hai. Assignment value/reference copy karta hai, automatically deep clone nahi.', 'class Counter {\n    int count;\n    static int total;\n    void increment() {\n        int step = 1;\n        count += step;\n        total += step;\n    }\n}', 'Two separate Counters incremented once: each count = 1, shared total = 2.', 'count instance field hai aur initial default zero milta hai. total static shared field hai. step local variable explicitly initialized hai. count += step receiver object change karta hai; total += step common class state change karta hai.', 'Local variables ko fields ki tarah automatic default value nahi milti. Parallel tests mein mutable static data se cross-test interference ho sakta hai.', 'Local step per call > Instance count per object > Static total shared'),
('Data Types', 'Java mein eight primitive types hain: byte, short, int, long, float, double, char, boolean. Reference types mein String, arrays aur application classes aati hain. Primitive value aur reference assignment ko separate samjho. Numeric widening often automatic hoti hai; narrowing cast data lose kar sakta hai. Money ke exact decimal rules ke liye BigDecimal often better hai.', 'int attempts = 3;\nlong largeCount = 3000000000L;\ndouble average = 5 / 2;\ndouble precise = 5 / 2.0;\nSystem.out.println(average + " / " + precise);', '2.0 / 2.5', '5 aur 2 int operands hain, isliye division integer arithmetic se 2 banati hai; baad mein double assignment 2.0 banata hai. 2.0 operand division ko floating-point banata hai. L literal ko long declare karta hai.', 'double result variable rakhne se integer division ki lost fraction wapas nahi aati. int overflow silently wrap kar sakta hai.', 'Operand types > Arithmetic rule > Result conversion'),
('Wrapper Classes', 'Wrapper primitive value ko object API deta hai: int ka Integer, boolean ka Boolean. Collections generic type arguments primitives nahi lete, isliye List<Integer> chahiye. Autoboxing primitive se wrapper aur unboxing reverse conversion karti hai. Nullable wrapper optional value represent kar sakta hai, par null unbox karna failure hai.', 'Integer count = 10;\nint next = count + 1;\nInteger missing = null;\nSystem.out.println(next);\nSystem.out.println(missing == null);', '11\ntrue', '10 automatically Integer mein box hota hai. Arithmetic ke waqt count unbox hokar int banta hai. missing null hai, isliye null check safe hai; missing + 1 evaluate karoge to NullPointerException aayegi.', 'Wrapper equality ke liye == par rely mat karo: caching behavior values ke saath misleading result de sakta hai. Objects.equals nullable comparisons mein useful hai.', 'Primitive 10 > Boxing: Integer > Unboxing: arithmetic'),
('Operators', 'Operator values par calculation ya comparison perform karta hai. = assignment hai, == comparison. && aur || logical short-circuit operators hain: second operand tabhi evaluate hota hai jab required ho. Precedence expression ka grouping decide karti hai; readability ke liye parentheses useful hain. ++ mutable state change karta hai; compound expressions mein side effects ko avoid karo.', 'String name = null;\nboolean valid = name != null && !name.isBlank();\nint value = 2 + 3 * 4;\nSystem.out.println(valid);\nSystem.out.println(value);', 'false\n14', 'name != null false hai, isliye isBlank call evaluate nahi hoti. Multiplication addition se pehle hoti hai, so 3 * 4 = 12 and 2 + 12 = 14. Parentheses (2 + 3) * 4 result 20 deti hain.', 'Single & boolean operands ke saath dono sides evaluate karta hai; null guard ke liye short-circuit && chahiye. Object identity aur content equality separate hain.', 'Operands > Precedence / short circuit > Final value'),
('Decision Making: if/else', 'if/else mutually exclusive behavior choose karne ke liye use hota hai. Condition boolean expression honi chahiye. Multiple else-if branches top-to-bottom check hoti hain aur first matching branch chalti hai. QA engineer ko boundaries identify karni hain: exact threshold, one below aur one above. Order wrong ho to specific case unreachable ho sakta hai.', 'int age = 18;\nif (age < 0) {\n    System.out.println("Invalid");\n} else if (age >= 18) {\n    System.out.println("Adult");\n} else {\n    System.out.println("Minor");\n}', 'Adult', 'Negative input pehle reject hoti hai. age 18 negative nahi, phir >=18 true hai aur Adult print hota hai. Else remaining valid younger ages cover karta hai. Cases -1, 0, 17, 18, 19 branches/boundary test karte hain.', '>= aur > interchangeable nahi. Nested conditions bahut ho jaayein to guard clauses aur small methods se reasoning clear karo.', 'Validate age > Check adulthood > Adult or minor'),
('Decision Making: switch', 'switch discrete values ke different cases select karta hai. Java 17/21 baseline mein switch expression result directly assign kar sakti hai. Arrow syntax accidental fall-through avoid karti hai. Classic colon syntax mein break behavior samajhna zaroori hai. Default unexpected values ka rule define karta hai; nullable input ka behavior consciously handle karo.', 'int status = 404;\nString label = switch (status) {\n    case 200, 201 -> "Success";\n    case 404 -> "Missing";\n    default -> "Other";\n};\nSystem.out.println(label);', 'Missing', 'status 404 second case match karta hai. Switch expression Missing return karti hai, label store karta hai. Arrow case se next case execute nahi hota. Cases 200, 201 aur unknown 503 bhi test karo.', 'Classic case mein missing break unintended fall-through la sakta hai. Range checks ke liye if/else often clearer hai.', 'Input status > Matching case > Assigned label'),
('Loops', 'Loop repeated work express karta hai. for tab useful hai jab counter/range known ho; while condition-based repeat karta hai; do-while body at least once chalata hai. Enhanced for collection/array values read karne ke liye simple hai. Loop invariant socho: har iteration ke baad kya guaranteed hai? Termination bhi explicitly reason karo.', 'int[] values = {2, 4, 6};\nint sum = 0;\nfor (int value : values) {\n    sum += value;\n}\nSystem.out.println(sum);', '12', 'sum initially zero hai. Iteration values 2,4,6 se running total 2,6,12 banta hai. Empty array se body zero times chalegi aur sum zero rahega. Index loop mein i < length valid range preserve karta hai.', 'i <= array.length se last iteration invalid index milta hai. Retry loop ko maximum attempts aur useful wait condition ke bina endless mat banao.', 'Initial sum 0 > Each element adds value > Final sum 12'),
('Jump Statements', 'break nearest loop ya switch se exit karta hai; continue current iteration ka remaining body skip karke next iteration start karta hai; return enclosing method end karta hai. In teen effects ko mix karne se bugs aate hain. Early return invalid input reject karne mein useful hai. Nested loop mein plain break only inner loop rokta hai.', 'for (int n = 1; n <= 5; n++) {\n    if (n == 2) continue;\n    if (n == 4) break;\n    System.out.println(n);\n}', '1\n3', '1 print hota hai. 2 par continue print skip karta hai. 3 print hota hai. 4 par break loop stop karta hai, isliye 4 aur 5 print nahi hote. return use hota to method ka baaki code bhi execute nahi hota.', 'continue se counter update skip hone wala while loop infinite ho sakta hai. Labeled jumps se pehle simpler method structure consider karo.', 'Iteration > continue skips body > break exits loop'),
])

add(4, [
('Classes & Objects', 'Class blueprint define karti hai: fields state aur methods behavior. Object us blueprint ki runtime instance hai. Account class ek type hai; Harsh ka account aur Anvikha ka account two instances hain. new allocation aur initialization initiate karta hai. Variable object ka reference hold karti hai, object ka deep copy nahi. Isliye aliasing ko trace karna QA debugging mein useful hai.', 'class Account {\n    int balance;\n    Account(int balance) { this.balance = balance; }\n}\n// Inside main:\nAccount a = new Account(100);\nAccount b = a;\nb.balance = 150;\nSystem.out.println(a.balance);', '150', 'a new instance refer karta hai. b = a same reference value copy karta hai. b.balance assignment shared object change karta hai, so a se read bhi 150 hai. new Account(100) dobara likhne se separate object milega.', 'Reference assignment ko cloning mat samjho. Shared test objects mutate karoge to later cases unexpected state receive kar sakte hain.', 'a reference > One Account object > b aliases same object'),
('Constructors', 'Constructor object initialization ka special member hai: class ke same name aur no return type. Required values aur validation yahan establish kar sakte ho. No-arg aur parameterized constructors overloaded ho sakte hain. Compiler default no-arg constructor tabhi supply karta hai jab class mein koi constructor declared na ho. Constructor inherited nahi hota; subclass apna constructor define karti hai.', 'class Account {\n    private int balance;\n    Account() { this(0); }\n    Account(int balance) {\n        if (balance < 0) throw new IllegalArgumentException("balance");\n        this.balance = balance;\n    }\n    int balance() { return balance; }\n}\n// Inside main:\nSystem.out.println(new Account(100).balance());', '100', 'new Account(100) int constructor choose karta hai. Validation negative starting balance prevent karti hai. this.balance field receive karti hai. No-arg constructor same-class int constructor ko zero pass karke initialization reuse karta hai.', 'void Account() constructor nahi, ordinary method hai. Java 17/21 examples mein this(...) ya super(...) first statement rakho; JDK 25 restricted constructor prologues allow karta hai.', 'new with argument > Constructor validation > Initialized object'),
('this Keyword', 'this current object ka reference hai: jis instance ka constructor ya instance method abhi execute ho raha hai. Har object ka apna state hota hai; this current receiver select karta hai. Suppose field aur parameter dono balance naam se hain: plain balance nearest local parameter ko refer karega, this.balance object field ko. this koi naya object create nahi karta aur superclass ka separate object bhi nahi hota.', 'class Account {\n    private int balance;\n    Account() { this(0); }\n    Account(int balance) { this.balance = balance; }\n    Account deposit(int amount) {\n        if (amount <= 0) throw new IllegalArgumentException("amount");\n        this.balance += amount;\n        return this;\n    }\n    int balance() { return this.balance; }\n}\n// Inside main:\nAccount a = new Account(100);\nAccount b = new Account(300);\nAccount same = a.deposit(20);\nSystem.out.println(a.balance());\nSystem.out.println(b.balance());\nSystem.out.println(same == a);', '120\n300\ntrue', 'Account(int balance) mein right side balance supplied parameter hai; left this.balance receiver ka field. a.deposit(20) execute hote waqt this a ka object hai, so only a changes to 120. b stays 300. return this existing receiver return karta hai, isliye same == a true hai. Account() ka this(0) another constructor call karta hai; this.balance field access se isko confuse mat karo. Instance method this.check() se same-object method call kar sakti hai; register(this) current object collaborator ko pass karta hai. Constructor argument mein this pass possible hai, but partially initialized object leak karna avoid karo.', 'balance = balance parameter ko khud assign karega aur field unchanged rahegi. static method mein implicit current instance nahi, so this compilation error hai. Constructor chaining cycle allowed nahi. Java 17/21 mein this(...) first statement hai; JDK 25 mein limited code-before-delegation allowed hai.', 'a: Account(100) > this during a.deposit(20) > a.balance becomes 120 > b remains 300'),
('super Keyword', 'super inherited parent implementation access karne ka syntax hai. this current receiver ko refer karta hai; super separate parent instance create nahi karta. super(...) immediate superclass constructor call karta hai. super.method() overridden parent behavior deliberately invoke karta hai. Parent private field direct access nahi milti, so accessible operations use karo.', 'class Parent {\n    Parent(String name) { System.out.println(name); }\n    String role() { return "Parent"; }\n}\nclass Child extends Parent {\n    Child() { super("Harsh"); }\n    @Override String role() { return super.role() + " + Child"; }\n}\n// Inside main:\nSystem.out.println(new Child().role());', 'Harsh\nParent + Child', 'Child construction first parent constructor initialize karti hai. role override parent method result reuse karke child-specific part add karti hai. super.role bypasses child override for that call, recursion avoid karta hai.', 'Parent ke paas usable no-arg constructor nahi ho to implicit super() fail hota hai. this(...) aur super(...) dono same constructor mein delegation calls nahi rakh sakte.', 'Child creation > Parent constructor > Child override calls parent behavior'),
('Encapsulation', 'Encapsulation state aur valid operations ko same boundary mein rakhti hai. Private fields alone enough nahi: public setter agar invalid values accept kare to rule break hota hai. Account ko deposit operation do jo positive amount require kare. Caller implementation storage jaane bina domain behavior use kare. QA contract valid transitions aur rejected transitions dono verify kare.', 'class Wallet {\n    private int balance;\n    void deposit(int amount) {\n        if (amount <= 0) throw new IllegalArgumentException("amount");\n        balance += amount;\n    }\n    int balance() { return balance; }\n}\n// Inside main:\nWallet w = new Wallet();\nw.deposit(50);\nSystem.out.println(w.balance());', '50', 'Caller direct balance assignment nahi kar sakta. deposit validates positive input before mutation. Failed deposit should preserve previous balance. Getter observation provide karta hai; update business operation ke through hota hai.', 'Har private field ka unrestricted setter generate karna encapsulation purpose defeat kar sakta hai. Mutable collection getter defensive copy ya controlled view de.', 'Caller deposit > Validate invariant > Private state changes'),
('Inheritance', 'Inheritance is-a relation express karti hai. SavingsAccount Account ka specialized type ho sakti hai, par Account EmailSender nahi. Child accessible behavior reuse aur override kar sakti hai. Java classes single direct superclass extend karti hain, interfaces multiple implement kar sakti hain. Shared utility use ke liye has-a composition often clearer hai.', 'class Account {\n    String kind() { return "Account"; }\n}\nclass SavingsAccount extends Account {\n    int interestRate() { return 3; }\n}\n// Inside main:\nSavingsAccount a = new SavingsAccount();\nSystem.out.println(a.kind());\nSystem.out.println(a.interestRate());', 'Account\n3', 'SavingsAccount parent kind method inherit karti hai. interestRate child-specific method hai. Account variable child object hold kar sakti hai but child-only method compile-time type se directly available nahi hoti.', 'Private members direct child access nahi dete. Inheritance sirf code reuse ke liye deep hierarchy banana fragile design la sakta hai.', 'Account contract > SavingsAccount subtype > Inherited + specialized behavior'),
('Polymorphism', 'Polymorphism same declared contract ke through different runtime implementations execute karna hai. PaymentGateway reference CardGateway ya StubGateway hold kar sakti hai. Overridden instance method selection actual object se hota hai. Overloading compile-time argument types se choose hoti hai; static method hiding dynamic override nahi. QA mein interchangeable fakes isi idea se possible hain.', 'class Gateway { String pay() { return "generic"; } }\nclass CardGateway extends Gateway {\n    @Override String pay() { return "card approved"; }\n}\n// Inside main:\nGateway gateway = new CardGateway();\nSystem.out.println(gateway.pay());', 'card approved', 'Variable type Gateway valid operations decide karta hai. Actual object CardGateway hai, so its pay override run hota hai. Caller implementation select kiye bina gateway contract use karta hai.', 'Fields dynamically dispatched nahi. Overload ko override samajhne se unexpected method selection ho sakti hai; @Override annotation use karo.', 'Gateway reference > Runtime CardGateway object > Overridden pay executes'),
('Abstraction', 'Abstraction caller ko meaningful contract dikhati hai aur implementation details hide karti hai. Abstract class shared fields/concrete operations ke saath incomplete abstract operations define kar sakti hai. Abstract class directly instantiate nahi hoti. Interface especially replaceable collaborators ke liye useful hai; choice shared implementation aur type relationships se decide karo.', 'abstract class Report {\n    abstract String content();\n    String render() { return "Report: " + content(); }\n}\nclass QaReport extends Report {\n    @Override String content() { return "3 passed"; }\n}\n// Inside main:\nSystem.out.println(new QaReport().render());', 'Report: 3 passed', 'render reusable template hai. Abstract content child fulfill karti hai. render ke content() call par runtime QaReport implementation run hoti hai. Caller report rendering contract use karta hai.', 'Abstraction ka matlab every class abstract banana nahi. Poor contract ko hidden implementation fix nahi karti; inputs/failures clearly define karo.', 'Report abstract contract > QaReport supplies content > Shared render output'),
('Object Class', 'Object ordinary Java class hierarchy ka common root hai. toString diagnostic representation deta hai; equals logical equality define kar sakta hai; hashCode hash containers support karta hai. Default equals identity-based hai. Logical equals override karo to matching hashCode override compulsory contract hai. Records value-style implementations automatically generate kar sakte hain.', 'record PaymentId(String value) {}\n// Inside main:\nPaymentId a = new PaymentId("P1");\nPaymentId b = new PaymentId("P1");\nSystem.out.println(a.equals(b));\nSystem.out.println(a.hashCode() == b.hashCode());\nSystem.out.println(a);', 'true\ntrue\nPaymentId[value=P1]', 'Record components logical equality define karte hain. Same component values equal aur same hash code dete hain. toString readable state dikhata hai. Same hash code alone equality prove nahi karta, collisions possible hain.', 'Mutable identity fields map key ke hashing ko break kar sakte hain. Object.clone automatic deep copy nahi; finalize lifecycle cleanup ke liye use mat karo.', 'Object contract > equals / hashCode pair > Collection lookup + diagnostics'),
('Packages', 'Package related types ko namespace aur access boundary deta hai. com.example.bank.Account aur com.example.test.Account different fully qualified types hain. package declaration source ke top par hoti hai; directory layout typically name ke segments follow karta hai. import qualified type ka short name available karta hai, source code copy nahi.', 'package com.example.bank;\nimport java.time.LocalDate;\npublic class Payment {\n    LocalDate bookedOn = LocalDate.of(2026, 9, 30);\n}', 'Defines com.example.bank.Payment with a LocalDate field.', 'package exact type namespace establish karta hai. import java.time.LocalDate use site par short LocalDate allow karta hai. java.lang types automatically available hain. Maven sources mein path com/example/bank/Payment.java rakho.', 'Wildcard import subpackages automatically import nahi karta. Unnamed/default package production structure mein avoid karo.', 'Directory namespace > Fully qualified class > Import short name'),
])

add(5, [
('Interfaces', 'Interface behavior contract hai: caller ko kya operation milega. Implementing class abstract operations fulfill karti hai. Interface fields constants hote hain; default aur static methods possible hain, so interfaces mein implementation kabhi nahi hoti kehna wrong hai. Constructor injection se real HTTP client ke jagah fake supply kar sakte ho.', 'interface Gateway { boolean pay(int amount); }\nclass FakeGateway implements Gateway {\n    public boolean pay(int amount) { return amount > 0; }\n}\n// Inside main:\nGateway g = new FakeGateway();\nSystem.out.println(g.pay(100));', 'true', 'Gateway allowed operation define karta hai. FakeGateway public implementation provide karta hai. Caller interface variable se pay invoke karta hai. Different implementation swap karne se caller code unchanged reh sakta hai.', 'Implementing method visibility reduce nahi kar sakte. Interface reference ka matlab object automatically mock nahi ban gaya.', 'Gateway contract > FakeGateway implements > Caller invokes contract'),
('Class vs Interface', 'Class object state, constructors aur implementation define karti hai. Interface capability contract define karti hai. Class one superclass extend kar sakti hai aur multiple interfaces implement kar sakti hai. Abstract class shared state/behavior ke liye suitable ho sakti hai; interface independent implementations ke substitutable API ke liye useful hai.', 'interface Auditable { String audit(); }\nclass Payment implements Auditable {\n    private final String id;\n    Payment(String id) { this.id = id; }\n    public String audit() { return "payment=" + id; }\n}', 'new Payment("P1").audit() returns payment=P1', 'Payment constructor instance state initialize karta hai. Auditable capability require karti hai. Another non-payment type bhi Auditable implement kar sakta hai without inheriting Payment state.', 'Interface mein instance constructor nahi hota. Default methods ko uncontrolled shared business behavior bana dena conflicts introduce kar sakta hai.', 'Class owns state > Interface defines capability > Implementation fulfills API'),
('Functional Interface', 'Functional interface ka exactly one abstract method hota hai, Object-compatible method exceptions ke rules ke saath. Ye lambda ka target type ban sakti hai. Default/static methods extra ho sakte hain. @FunctionalInterface compiler ko intention check karne deta hai. Predicate, Consumer aur Supplier standard examples hain.', '@FunctionalInterface\ninterface Rule { boolean matches(int status); }\n// Inside main:\nRule success = status -> status >= 200 && status < 300;\nSystem.out.println(success.matches(201));', 'true', 'matches single abstract contract hai. Lambda status parameter lekar boolean expression return karti hai. target Rule type se compiler parameter type infer karta hai. Status 199/200/299/300 useful boundaries hain.', 'Second abstract method add karoge to functional interface annotation fail karegi. Lambda ko anonymous class ke this behavior se confuse mat karo.', 'Single abstract method > Lambda implementation > matches result'),
('Nested Interface', 'Nested interface kisi enclosing type ke context mein contract organize karti hai. Example TestRunner.Listener callback role hai jo runner se logically related hai. Member interfaces implicitly static hoti hain; outer object create kiye bina type refer kar sakte ho. Visibility enclosing declaration aur modifier rules se control hoti hai.', 'class TestRunner {\n    interface Listener { void completed(String name); }\n}\n// Inside main:\nTestRunner.Listener listener = System.out::println;\nlistener.completed("smoke");', 'smoke', 'Qualified name TestRunner.Listener role clear karta hai. Method reference compatible single-argument void contract fulfill karti hai. No TestRunner instance needed to name this interface.', 'Nested interface ko non-static inner class samajhkar outer.new syntax use mat karo. Public API mein unnecessary nesting readability reduce kar sakti hai.', 'Enclosing TestRunner type > Listener contract > Callback implementation'),
('Marker Interface', 'Marker interface declared methods ke bina type information encode karti hai. Serializable historical example hai: implementing type opt-in capability indicate karta hai. Marker operational behavior khud execute nahi karti; library/code ko check aur use karna hota hai. Annotations metadata alternative hain, but type constraints ke liye interface useful ho sakti hai.', 'interface Retryable {}\nclass TemporaryFailure implements Retryable {}\n// Inside main:\nObject failure = new TemporaryFailure();\nSystem.out.println(failure instanceof Retryable);', 'true', 'TemporaryFailure marker implement karti hai. instanceof runtime capability check deta hai. Retry policy ko is result ke saath actual safety rules bhi evaluate karne chahiye; marker alone retry perform nahi karta.', 'Serializable declare karna object graph ko automatically secure ya all fields serializable nahi banata. Marker ko vague category ke liye indiscriminately add mat karo.', 'Type implements marker > Runtime type check > Policy decides action'),
])

add(1, [
('Methods Introduction', 'Method named behavior hai jo input parameters lekar result return ya side effect perform karta hai. Signature caller ko allowed inputs batati hai. Small method ka contract clear hona chahiye: precondition kya hai, output kya hai, failure kaise report hoti hai? Java always pass-by-value hai; object argument mein reference ki value copy hoti hai.', 'static int total(int price, int quantity) {\n    if (quantity < 0) throw new IllegalArgumentException("quantity");\n    return price * quantity;\n}\n// Call inside main:\nSystem.out.println(total(50, 3));', '150', 'Caller 50 aur 3 pass karta hai. Parameters local names mein copies receive hoti hain. Guard negative quantity reject karta hai. Multiplication result caller ko return hota hai; caller print karta hai.', 'Method ke andar parameter reference reassign karna caller variable reassign nahi karta. Shared object mutate karna caller ko visible ho sakta hai.', 'Arguments > Parameter copies + calculation > Returned result'),
('Static vs Instance Methods', 'Static method class-level operation hai; instance method receiver object ki state use karti hai. Math.max utility static hai; account.deposit object-specific hai. Instance method ke paas implicit this receiver hota hai. Static method ke paas implicit current object nahi hota, so field access ke liye explicit object chahiye.', 'class Score {\n    int value = 5;\n    int doubled() { return value * 2; }\n    static int add(int a, int b) { return a + b; }\n}\n// Inside main:\nSystem.out.println(new Score().doubled());\nSystem.out.println(Score.add(2, 3));', '10\n5', 'new Score receiver create karta hai; doubled uska value field read karti hai. Score.add class name se call hota hai aur supplied operands use karta hai. Separate Score objects separate value rakh sakte hain.', 'static method mein this use karna compilation error hai. Testability ke liye every collaborator ko static utility mein convert mat karo.', 'Instance receiver > Object field access > Static call uses arguments'),
('Access Modifiers', 'Visibility API boundary define karti hai. private same class, package-private same package, public accessible users, protected same package aur subclass rules deta hai. Top-level ordinary class public ya package-private ho sakti hai. Encapsulation ke liye smallest useful visibility choose karo; har field public karna valid states enforce karna mushkil banata hai.', 'package bank;\npublic class Account {\n    private int balance = 100;\n    public int balance() { return balance; }\n    void audit() { System.out.println(balance); }\n}', 'balance() returns 100; direct external balance access does not compile.', 'Private field internal hai. Public read operation external API hai. audit mein no modifier hai, so same package callers use kar sakte hain. protected ko simply public-to-children kehna incomplete hai, especially cross-package receivers.', 'Default visibility ko default keyword mat likho. Cross-package protected access ke receiver restrictions ko check karo.', 'Private internal state > Package collaborators > Public API callers'),
('Command Line Arguments', 'main ka String[] args launcher ke supplied tokens receive karta hai. Java options aur application arguments separate positions par hote hain. Arguments text hain, so numeric input parse aur validate karna padta hai. CLI test runner mein environment, suite aur retry count pass kar sakte ho. Missing arguments ko useful message ke saath handle karo.', 'class ArgsDemo {\n    public static void main(String[] args) {\n        if (args.length == 0) {\n            System.out.println("Usage: java ArgsDemo <suite>");\n            return;\n        }\n        System.out.println("Suite: " + args[0]);\n    }\n}', 'java ArgsDemo smoke prints Suite: smoke', 'Launcher smoke ko first element args[0] banata hai. Empty args par guard usage print karke return karta hai. Spaces wale single argument ko shell quoting chahiye. Numeric parse mein NumberFormatException relevant failure hai.', 'args[0] bina length check use karna empty input par ArrayIndexOutOfBoundsException deta hai. Secrets ko command line arguments mein avoid karo.', 'Shell tokens > main String[] args > Validate and use'),
('Varargs', 'Varargs method caller ko zero ya multiple same-type arguments dene deta hai. Method ke andar values ordinary array ki tarah accessible hoti hain. Declaration mein type... syntax hoti hai aur varargs parameter last hona chahiye. Ye convenience hai, unlimited runtime resource nahi; large datasets ke liye collection API clearer ho sakti hai.', 'static int sum(int... values) {\n    int result = 0;\n    for (int value : values) result += value;\n    return result;\n}\n// Inside main:\nSystem.out.println(sum(1, 2, 3));\nSystem.out.println(sum());', '6\n0', 'Compiler arguments ko int array ke form mein method tak pahunchata hai. Enhanced for har element add karta hai. Zero arguments empty array dete hain aur zero return hota hai. Existing int[] bhi pass kar sakte ho.', 'Only one varargs parameter allowed hai aur last position chahiye. Explicit null array pass karne se iteration NPE de sakti hai.', 'Variable argument count > Array parameter > Loop result'),
])

add(2, [
('Arrays Introduction', 'Array fixed-length indexed container hai. Length creation ke baad change nahi hoti; elements replace ho sakte hain. Valid indices zero se length minus one tak hain. Primitive array elements default values lete hain; object-reference elements initially null ho sakte hain. Test datasets ke small known groups ke liye array useful hai.', 'int[] statuses = {200, 400, 500};\nSystem.out.println(statuses[0]);\nstatuses[1] = 404;\nSystem.out.println(statuses.length);', '200\n3', 'Initializer three slots create karta hai. Index zero first value hai. statuses[1] second slot update karta hai, array length nahi. Empty array length zero hai aur koi valid index nahi.', 'Array variable copy karne se same array reference milta hai. Independent elements chahiye to clone/copy aur nested objects ke rules samjho.', 'Reference statuses > Indexed slots 0 1 2 > Read or replace element'),
('Multi-Dimensional Arrays', 'Java two-dimensional array technically array of arrays hai. Outer index row select karta hai; inner index column. Rectangular initialization se equal-length rows milti hain, par language rows ko different length bhi allow karti hai. Table-style QA datasets mein row scenario aur column values represent kar sakte hain.', 'int[][] matrix = {{1, 2}, {3, 4}};\nSystem.out.println(matrix[1][0]);\nSystem.out.println(matrix.length);\nSystem.out.println(matrix[0].length);', '3\n2\n2', 'matrix[1] second row {3,4} select karta hai. Us row ka [0] first element 3 deta hai. Outer length rows count hai; row length columns count hai. Nested loops har row ki length separately use karein.', 'matrix.length ko columns count samajhna rectangular assumptions laata hai. Outer array ki shallow copy inner rows share karti hai.', 'Outer array > Selected row array > Selected cell'),
('Jagged Arrays', 'Jagged array mein rows ki lengths unequal hoti hain. Ye varying test inputs ya grouped data ke liye natural representation hai. new int[3][] outer rows allocate karta hai par inner rows initially null hoti hain. Har row initialize karo ya null case handle karo. Iteration current row ke length se honi chahiye.', 'int[][] groups = {{10}, {20, 30, 40}};\nfor (int[] row : groups) {\n    System.out.println(row.length);\n}', '1\n3', 'Outer container two row references rakhta hai. First row one slot aur second three slots rakhti hai. Enhanced for actual row receive karta hai; row.length accurate per-row size deta hai.', 'First row ki length sab rows ke liye use karne se values miss ya bounds failure ho sakta hai. Null rows ko empty arrays se confuse mat karo.', 'Outer group > Row A: 1 cell > Row B: 3 cells'),
('Arrays Utility Class', 'java.util.Arrays static helpers array operations simplify karte hain: sort, equals, copyOf, toString aur binarySearch. Primitive array ka direct println readable elements nahi deta; toString useful hai. Binary search sorted array require karti hai. copyOf new outer array banata hai, par object elements ki deep copies nahi.', 'int[] ids = {3, 1, 2};\njava.util.Arrays.sort(ids);\nSystem.out.println(java.util.Arrays.toString(ids));\nSystem.out.println(java.util.Arrays.binarySearch(ids, 2));', '[1, 2, 3]\n1', 'sort original ids ko in-place modify karta hai. toString readable values deta hai. Sorted ids mein 2 index one par hai. Missing value ke liye binarySearch negative insertion-point encoding return karti hai, simply -1 always nahi.', 'Arrays.asList primitive int[] ko Integer elements ki list nahi banata. Returned object-array list fixed-size hai, add/remove unsupported hain.', 'Unsorted array > sort mutates order > binarySearch finds index'),
('Final Arrays', 'final array variable ko dusri array reference assign karna rokta hai. Ye existing array ko immutable nahi banata. Elements mutate ho sakte hain kyunki final reference assignment rule hai, object freeze rule nahi. Test fixtures mein final config array share karna bhi interference create kar sakta hai agar tests elements change karein.', 'final int[] values = {10, 20};\nvalues[0] = 99;\nSystem.out.println(values[0]);\n// values = new int[]{1}; // compilation error', '99', 'values same array par point karta rehta hai. Slot zero ki value replace hoti hai. Commented reassignment reference replace karne ki attempt hai, so final reject karta hai. Defensive copying state protection ka alag mechanism hai.', 'final ko immutable ka synonym mat samjho. Getter se private array directly return karna external mutation allow karta hai.', 'Final reference stays fixed > Array object remains same > Element can change'),
])

add(3, [
('Strings Introduction', 'String characters ka immutable sequence represent karti hai. Literal, constructor aur API results String values de sakte hain. Immutable ka meaning existing object change nahi hota; variable new String refer kar sakti hai. char UTF-16 code unit hai, so all visible characters necessarily one char nahi. Response-body text compare karte waqt normalization requirement se decide karo.', 'String greeting = "Hei";\nString expanded = greeting + " Harsh";\nSystem.out.println(greeting);\nSystem.out.println(expanded);', 'Hei\nHei Harsh', 'Concatenation result expanded receive karta hai. Original greeting object text Hei hi rehta hai. String variable reassign karna allowed hai, par original object mutate nahi hota.', 'String null aur empty string alag hain. User-visible character count ke liye length always enough nahi, especially emoji.', 'Original text Hei > Concatenation creates result > Original unchanged'),
('== vs equals()', 'References ke saath == identity compare karta hai: kya dono same object ko refer karte hain? String.equals content compare karti hai: characters same hain? Literal pooling se == kabhi true dikh sakta hai, par ye content comparison ka reliable contract nahi. API, database aur file strings ke assertions content-based honi chahiye.', 'String a = new String("PASS");\nString b = new String("PASS");\nSystem.out.println(a == b);\nSystem.out.println(a.equals(b));', 'false\ntrue', 'Two new calls independent objects banati hain, so references unequal. Dono ka text PASS hai, so equals true. Nullable strings ke liye Objects.equals(a,b) null-safe hai. equalsIgnoreCase only jab requirement case-insensitive ho.', 's.equals(...) null receiver par NPE deta hai. Enum identity comparison valid hai; every reference ke liye == ko universally wrong kehna bhi galat hai.', 'Two references > Identity check: false > Content check: true'),
('String Methods', 'String APIs searching, slicing aur cleaning mein useful hain. contains substring existence check karti hai; indexOf location ya -1 deti hai; substring start inclusive aur end exclusive hai. strip Unicode-aware whitespace remove karti hai. replace literal replacement hai, replaceAll regex interpret karti hai. Har transformation ka returned result capture karo.', 'String raw = "  payment-123  ";\nString cleaned = raw.strip();\nSystem.out.println(cleaned.substring(0, 7));\nSystem.out.println(cleaned.contains("123"));', 'payment\ntrue', 'strip outer whitespace remove karke new value deta hai. substring indices zero through six take karta hai. contains token existence check karta hai. raw untouched hai. Bounds test mein empty, shorter input aur exact expected length include karo.', 'replaceAll mein dot regex wildcard hai, literal dot nahi. Upper/lower case conversion mein locale-sensitive requirements handle karo.', 'Raw text > strip result > substring / contains'),
('String Class & Immutability', 'String immutability sharing ko safer banati hai: caller text ko mutate nahi kar sakta. Methods jo different result dete hain generally new value return karte hain. Reference variable change ho sakti hai; object contents fixed rehte hain. String pool literal reuse kar sakta hai, but application logic identity optimization par depend nahi karni chahiye.', 'String name = "harsh";\nname.toUpperCase(java.util.Locale.ROOT);\nSystem.out.println(name);\nname = name.toUpperCase(java.util.Locale.ROOT);\nSystem.out.println(name);', 'harsh\nHARSH', 'First conversion result ignore hota hai; name old lowercase value refer karta hai. Second call returned value assign karti hai, so variable now uppercase string refer karti hai. This is reassignment, mutation nahi.', 'Password string memory se immediately erase nahi kar sakte. Repeated concatenation loop mein unnecessary intermediate values bana sakti hai.', 'Original object > Transform returns value > Assign new reference'),
('StringBuilder', 'StringBuilder mutable text buffer hai, especially repeated append ke liye. Same builder content change hota hai; final toString String snapshot deta hai. Capacity internal storage space hai aur length actual text count. Local single-thread use natural hai. Test report, dynamic SQL placeholders ya long log formatting mein useful ho sakta hai.', 'StringBuilder report = new StringBuilder();\nreport.append("Passed: ").append(3);\nString snapshot = report.toString();\nreport.append(" tests");\nSystem.out.println(snapshot);\nSystem.out.println(report);', 'Passed: 3\nPassed: 3 tests', 'append same mutable builder return karta hai, so chaining possible hai. Snapshot String later builder mutation se change nahi hoti. report print latest content show karta hai.', 'StringBuilder shared across threads without coordination thread-safe nahi. Untrusted SQL values string append karke query mat banao; PreparedStatement use karo.', 'Mutable builder > append changes buffer > toString immutable snapshot'),
('StringBuffer', 'StringBuffer mutable text buffer hai jiske individual methods synchronized hain. Ye method-level coordination provide karta hai, lekin multiple calls ka business operation automatically atomic nahi hota. Agar har thread independent text build kar rahi hai to StringBuilder simpler choice hoti hai. Thread safety ko actual shared access boundary par reason karo.', 'StringBuffer text = new StringBuffer("QA");\ntext.append(" ").append("Report");\nSystem.out.println(text);', 'QA Report', 'Constructor initial content rakhta hai. Har append method synchronized access se content extend karti hai. Printed text latest buffer value hai. Compound sequence check-length-then-append ko one unit banana ho to extra coordination chahiye.', 'Synchronized methods ka matlab complete workflow race-free nahi. Lock overhead ko correctness requirements ke baad evaluate karo.', 'Shared buffer > Synchronized single operation > Updated text'),
('String vs StringBuilder vs StringBuffer', 'Choice mutation aur ownership par depend karti hai. String stable text value hai. StringBuilder editable buffer hai for one thread. StringBuffer synchronized mutable buffer hai. Simple one-line concatenation ko blindly builder mein rewrite karna zaroori nahi; readable code aur measured hotspot important hain. Report generation mein per-test builder shared buffer se easier ho sakta hai.', 'String fixed = "QA";\nStringBuilder local = new StringBuilder(fixed);\nlocal.append(" test");\nStringBuffer shared = new StringBuffer(fixed);\nshared.append(" report");\nSystem.out.println(fixed);\nSystem.out.println(local);\nSystem.out.println(shared);', 'QA\nQA test\nQA report', 'fixed original unchanged rehta hai. local aur shared apne mutable buffers update karte hain. Inko independent variables rakhne se behavior side-by-side visible hai. APIs expecting String ko toString result do.', 'StringBuffer method synchronization string result ko business-level consistency guarantee nahi karti. Mutable buffers ko map keys banana avoid karo.', 'Stable String > Local mutable Builder > Synchronized mutable Buffer'),
])

def slug(text):
    return re.sub(r'[^a-z0-9]+', '-', text.lower()).strip('-')

sources = {
    16: 'https://docs.oracle.com/javase/tutorial/jdbc/',
    17: 'https://junit.org/junit5/docs/current/user-guide/',
    18: 'https://docs.spring.io/spring-framework/reference/6.2/core/beans.html',
    19: 'https://docs.spring.io/spring-boot/3.5/reference/',
    20: 'https://docs.spring.io/spring-data/jpa/reference/3.5/',
    21: 'https://docs.spring.io/spring-cloud/docs/current/reference/html/',
    22: 'https://kafka.apache.org/documentation/',
    23: 'https://docs.docker.com/get-started/',
    24: 'https://docs.spring.io/spring-ai/reference/',
    25: 'https://modelcontextprotocol.io/docs/learn/architecture',
}

result = dict(modules=original['modules'], lessons=[], legacy={}, version='2026-09-30-depth-1')
used_ids = set()
for mi, module in enumerate(original['modules']):
    for ti, topic in enumerate(module['topics']):
        data = entries[(mi, topic)]
        base = next((l for l in original['lessons'] if l['moduleIndex'] == mi and l['topic'] == topic), None)
        if base is None:
            base = next(l for l in original['lessons'] if l['moduleIndex'] == mi and topic in l['covers'])
        focused = base['topic'] == topic
        l = copy.deepcopy(base)
        identifier = base['id'] if focused else slug(topic)
        if identifier in used_ids:
            identifier = f'{mi+1:02d}-' + identifier
        used_ids.add(identifier)
        l.update(id=identifier, topic=topic, number=len(result['lessons'])+1,
                 covers=[topic], notes=[], topicIndex=ti, diagram=data['diagram'],
                 pitfall=data['mistake'], focusedCode=data['code'], focusedOutput=data['output'],
                 focusedWalk=data['trace'], legacyId=base['id'],
                 snippetLabel=('JAVA / SHELL FOCUSED EXAMPLE' if mi<16 else 'PROJECT FRAGMENT / POLICY EXAMPLE'),
                 reference=sources.get(mi, 'https://dev.java/learn/'),
                 relatedWorkshop=base['topic'])
        # Preserve original workshop depth as context, while the new article starts
        # with its own topic rather than repeating the combined workshop title.
        sentences = re.split(r'(?<=[.!?])\s+(?=[A-Z])', data['explanation'])
        mid = max(1, len(sentences)//2)
        l['concept'] = [' '.join(sentences[:mid]), ' '.join(sentences[mid:])]
        l['chapterConcept'] = base['concept']
        l['normal'] = base['normal']
        l['minutes'] = max(10, round((len(data['explanation'].split())+len(data['trace'].split())+len(data['mistake'].split())+sum(len(p.split()) for p in base['concept']))/45)+5)
        l['practice'] = f'Focused exercise: {topic}. Pehle example ka output predict karo. Phir input ya ek relevant condition badlo aur result explain karo. Common mistake ko reproduce karke corrected behavior verify karo: '+data['mistake']
        l['interview'] = [
            ['Is topic ka mechanism apne words mein?', data['trace']],
            ['Kaunsi common mistake aur kyun?', data['mistake']],
        ] + base['interview']
        l['slides'] = [
            {'title': topic+' · Basic idea', 'text': l['concept'][0], 'code':''},
            {'title': 'Mechanism samjho', 'text': l['concept'][1], 'code':''},
            {'title': 'Focused code ko trace karo', 'text':data['trace'], 'code':data['code']},
            {'title': 'Expected output / behavior', 'text':data['output'], 'code':data['code']},
            {'title': 'Common mistake', 'text':data['mistake'], 'code':''},
            {'title': 'QA chapter example', 'text':base['qa'], 'code':base['qacode']},
            {'title': 'Khud practice karo', 'text':l['practice'], 'code':''},
        ]
        result['lessons'].append(l)
        result['legacy'].setdefault(base['id'], identifier)

this = next(l for l in result['lessons'] if l['topic']=='this Keyword')
this['qacode'] = '''class LoginPage {
    private final String baseUrl;
    private String username;
    LoginPage(String baseUrl) { this.baseUrl = baseUrl; }
    LoginPage enterUsername(String username) {
        this.username = username;
        return this;
    }
    String summary() { return baseUrl + " / " + username; }
}
public class ThisQaDemo {
    public static void main(String[] args) {
        LoginPage page = new LoginPage("https://test.example");
        LoginPage returned = page.enterUsername("harsh");
        System.out.println(returned == page);
        System.out.println(page.summary());
    }
}'''
this['qa'] = 'QA page-object mein constructor this.baseUrl = baseUrl injected configuration ko object field mein store karta hai. enterUsername ka this.username = username current page ki state set karta hai. return this same page object return karta hai, isliye fluent same-page methods chain ho sakte hain. Ye model browser open nahi karta: Selenium/Playwright operations us page object mein separately add hongi. Navigation dusre page par ho to correct new page type return karna chahiye.'
this['qaOutput'] = 'true\nhttps://test.example / harsh'
this['qaRun'] = 'Save as ThisQaDemo.java, then javac ThisQaDemo.java and java ThisQaDemo.'
this['extra'] = [
    ['this.field', 'Current object ka field select karta hai. Same-name parameter shadowing resolve karne ke liye this.balance = balance use hota hai.'],
    ['this.method()', 'Current receiver ka instance method invoke karta hai. Many situations mein method() equivalent hai, par explicit receiver readability help kar sakta hai.'],
    ['this(...)', 'Same class ke another constructor ko delegate karta hai. Common initialization reuse karo; recursive constructor chain compiler reject karega. Java 17/21 examples first-statement rule follow karte hain.'],
    ['return this', 'Current receiver return karta hai. Same object ke fluent operations ke liye useful; new object/copy create nahi hoti.'],
    ['method(this)', 'Current object ko method argument pass karta hai, for example a listener registration. Collaborator retained reference lifetime consider karo.'],
    ['new Helper(this)', 'Current object constructor argument mein pass ho sakta hai. Apne constructor ke andar unfinished this publish karna unsafe initialization/visibility issues create kar sakta hai.'],
    ['Static context', 'Static operation ka implicit receiver nahi. Explicit Account reference use karo; static method ke andar this directly compile nahi hota.'],
    ['this vs super', 'this current object context hai; super inherited parent member/constructor selection hai. Dono two independent objects ke pointers nahi.'],
]
this['slides'][5] = {'title':'QA page-object: current receiver', 'text':this['qa'], 'code':this['qacode']}

assert len(result['lessons']) == 201
assert len(used_ids) == 201
assert set(entries) == {(mi,t) for mi,m in enumerate(original['modules']) for t in m['topics']}
(root/'course.json').write_text(json.dumps(result, ensure_ascii=False, indent=2)+'\n')
print(f"Created {len(result['lessons'])} dedicated lessons across {len(result['modules'])} chapters")
